export const GUIDED: Record<string, GuidedLab> = {"labex-matplotlib-creating-a-pie-chart-with-matplotlib":{"intro":"In this lab, you will learn how to create a pie chart using the Matplotlib library in Python. A pie chart is a circular chart that is divided into slices to represent numerical proportions.","steps":[{"title":"Import Matplotlib","body":["Before creating the pie chart, we need to import the Matplotlib library."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt"}]},{"title":"Define the Data","body":["Next, we need to define the data that will be used to create the pie chart. The data should be in the form of a list of values and a list of labels."],"code":[{"lang":"python","text":"labels = ['Frogs', 'Hogs', 'Dogs', 'Logs']\nsizes = [15, 30, 45, 10]"}]},{"title":"Create the Pie Chart","body":["To create the pie chart, we will use the pie() function from Matplotlib."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.pie(sizes, labels=labels)"}]},{"title":"Add Labels to the Slices","body":["We can add labels to the slices by passing a list of labels to the labels parameter of the pie() function."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.pie(sizes, labels=labels, autopct='%1.1f%%')"}]},{"title":"Customize the Colors","body":["We can customize the colors of the slices by passing a list of colors to the colors parameter of the pie() function."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.pie(sizes, labels=labels, colors=['olivedrab', 'rosybrown', 'gray', 'saddlebrown'])"}]},{"title":"Customize the Hatch Patterns","body":["We can customize the hatch patterns of the slices by passing a list of hatch patterns to the hatch parameter of the pie() function."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.pie(sizes, labels=labels, hatch=['**O', 'oO', 'O.O', '.||.'])"}]},{"title":"Explode the Slices","body":["We can explode one or more slices of the pie chart by passing a list of values to the explode parameter of the pie() function."],"code":[{"lang":"python","text":"explode = (0, 0.1, 0, 0)  # only \"explode\" the 2nd slice (i.e. 'Hogs')\n\nfig, ax = plt.subplots()\nax.pie(sizes, explode=explode, labels=labels, autopct='%1.1f%%',\n       shadow=True, startangle=90)"}]},{"title":"Control the Size","body":["We can control the size of the pie chart by setting the radius parameter of the pie() function."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.pie(sizes, labels=labels, autopct='%.0f%%',\n       textprops={'size': 'smaller'}, radius=0.5)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, ax = plt.subplots()\nax.pie(sizes, explode=explode, labels=labels, autopct='%1.1f%%',\n       shadow={'ox': -0.04, 'edgecolor': 'none', 'shade': 0.9}, startangle=90)"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-placing-text-boxes-in-matplotlib":{"intro":"In data visualization, it is often necessary to add annotations to plots to provide additional information to the audience. One way to do this is by adding text boxes to a plot. In Matplotlib, it is possible to place text boxes in axes coordinates, so the text doesn't move around with changes in x or y limits. You can also use the bbox property of text to surround the text with a ~matplotlib.patches.Patch instance.","steps":[{"title":"Creating a Jupyter Notebook and Preparing the Data","body":["![libraries-imported](../assets/screenshot-20250306-Azb1cb3S@2x.png)","This code imports two essential libraries:","• matplotlib.pyplot: A collection of functions that make matplotlib work like MATLAB • numpy: A fundamental package for scientific computing in Python","Now, let's create some sample data that we will visualize. In a new cell, enter and run the following code:"],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"},{"lang":"python","text":"# Set a random seed for reproducibility\nnp.random.seed(19680801)\n\n# Generate 10,000 random numbers from a normal distribution\nx = 30 * np.random.randn(10000)\n\n# Calculate basic statistics\nmu = x.mean()\nmedian = np.median(x)\nsigma = x.std()\n\n# Display the statistics\nprint(f\"Mean (μ): {mu:.2f}\")\nprint(f\"Median: {median:.2f}\")\nprint(f\"Standard Deviation (σ): {sigma:.2f}\")"},{"lang":"text","text":"Mean (μ): -0.31\nMedian: -0.28\nStandard Deviation (σ): 29.86"}]},{"title":"Creating a Basic Histogram","body":["Now that we have our data, let's create a histogram to visualize its distribution. A histogram divides the data into bins (ranges) and shows the frequency of data points within each bin.","When you run this cell, you should see a histogram displaying the distribution of your random data. The output will look like a bell-shaped curve (normal distribution) centered near zero.","Let's break down what each line in the code does:","• fig, ax = plt.subplots(figsize=(10, 6)): Creates a figure and axes object. The figsize parameter sets the size of the plot in inches (width, height)."],"code":[{"lang":"python","text":"# Create a figure and axes\nfig, ax = plt.subplots(figsize=(10, 6))\n\n# Create a histogram with 50 bins\nhistogram = ax.hist(x, bins=50, color='skyblue', edgecolor='black')\n\n# Add title and labels\nax.set_title('Distribution of Random Data', fontsize=16)\nax.set_xlabel('Value', fontsize=12)\nax.set_ylabel('Frequency', fontsize=12)\n\n# Display the plot\nplt.tight_layout()\nplt.show()"}]},{"title":"Adding a Text Box with Statistics","body":["Adding a Text Box with Statistics","Now that we have a basic histogram, let's enhance it by adding a text box that displays the statistical information about our data. This will make the visualization more informative for viewers.","First, we need to prepare the text content that will go inside our text box. In a new cell, enter and run the following code:","You should see output similar to:"],"code":[{"lang":"python","text":"# Create a string with the statistics\ntextstr = '\\n'.join((\n    r'$\\mu=%.2f$' % (mu,),           # Mean\n    r'$\\mathrm{median}=%.2f$' % (median,),  # Median\n    r'$\\sigma=%.2f$' % (sigma,)       # Standard deviation\n))\n\nprint(\"Text content for our box:\")\nprint(textstr)"},{"lang":"text","text":"Text content for our box:\n$\\mu=-0.31$\n$\\mathrm{median}=-0.28$\n$\\sigma=29.86$"},{"lang":"python","text":"# Create a new figure and axes\nfig, ax = plt.subplots(figsize=(10, 6))\n\n# Create a histogram with 50 bins\nhistogram = ax.hist(x, bins=50, color='skyblue', edgecolor='black')\n\n# Add title and labels\nax.set_title('Distribution of Random Data with Statistics', fontsize=16)\nax.set_xlabel('Value', fontsize=12)\nax.set_ylabel('Frequency', fontsize=12)\n\n# Define the properties of the text box\nproperties = dict(boxstyle='round', facecolor='wheat', alpha=0.5)\n\n# Add the text box to the plot\n# Position the box in the top left corner (0.05, 0.95) in axes coordinates\nax.text(0.05, 0.95, textstr, transform=ax.transAxes, fontsize=14,\n        verticalalignment='top', bbox=properties)\n\n# Display the plot\nplt.tight_layout()\nplt.show()"}]},{"title":"Customizing the Text Box","body":["Now that we have successfully added a text box to our plot, let's explore various customization options to make it more visually appealing and suitable for different contexts.","Experimenting with Different Styles","Let's create a function to make it easier to experiment with different text box styles. In a new cell, enter and run the following code:","Now, let's use this function to try different box styles. In a new cell, enter and run:"],"code":[{"lang":"python","text":"def plot_with_textbox(boxstyle, facecolor, alpha, position=(0.05, 0.95)):\n    \"\"\"\n    Create a histogram with a custom text box.\n\n    Parameters:\n    boxstyle (str): Style of the box ('round', 'square', 'round4', etc.)\n    facecolor (str): Background color of the box\n    alpha (float): Transparency of the box (0-1)\n    position (tuple): Position of the box in axes coordinates (x, y)\n    \"\"\"\n    # Create figure and plot\n    fig, ax = plt.subplots(figsize=(8, 5))\n    ax.hist(x, bins=50, color='skyblue', edgecolor='black')\n\n    # Set title and labels\n    ax.set_title(f'Text Box Style: {boxstyle}', fontsize=16)\n    ax.set_xlabel('Value', fontsize=12)\n    ax.set_ylabel('Frequency', fontsize=12)\n\n    # Create text box properties\n    box_props = dict(boxstyle=boxstyle, facecolor=facecolor, alpha=alpha)\n\n    # Add text box\n    ax.text(position[0], position[1], textstr, transform=ax.transAxes,\n            fontsize=14, verticalalignment='top', bbox=box_props)\n\n    plt.tight_layout()\n    plt.show()"},{"lang":"python","text":"# Try a square box with light green color\nplot_with_textbox('square', 'lightgreen', 0.7)\n\n# Try a rounded box with light blue color\nplot_with_textbox('round', 'lightblue', 0.5)\n\n# Try a box with extra rounded corners\nplot_with_textbox('round4', 'lightyellow', 0.6)\n\n# Try a sawtooth style box\nplot_with_textbox('sawtooth', 'lightcoral', 0.4)"},{"lang":"python","text":"# Create a figure with a 2x2 grid of subplots\nfig, axes = plt.subplots(2, 2, figsize=(12, 10))\naxes = axes.flatten()  # Flatten to easily iterate\n\n# Define positions for the four corners\npositions = [\n    (0.05, 0.95),  # Top left\n    (0.95, 0.95),  # Top right\n    (0.05, 0.05),  # Bottom left\n    (0.95, 0.05)   # Bottom right\n]\n\n# Define alignments for each position\nalignments = [\n    ('top', 'left'),          # Top left\n    ('top', 'right'),         # Top right\n    ('bottom', 'left'),       # Bottom left\n    ('bottom', 'right')       # Bottom right\n]\n\n# Corner labels\ncorner_labels = ['Top Left', 'Top Right', 'Bottom Left', 'Bottom Right']\n\n# Create four plots with text boxes in different corners\nfor i, ax in enumerate(axes):\n    # Plot histogram\n    ax.hist(x, bins=50, color='skyblue', edgecolor='black')\n\n    # Set title\n    ax.set_title(f'Text Box in {corner_labels[i]}', fontsize=14)\n\n    # Create text box properties\n    box_props = dict(boxstyle='round', facecolor='wheat', alpha=0.5)\n\n    # Add text box\n    ax.text(positions[i][0], positions[i][1], textstr,\n            transform=ax.transAxes, fontsize=12,\n            verticalalignment=alignments[i][0],\n            horizontalalignment=alignments[i][1],\n            bbox=box_props)\n\nplt.tight_layout()\nplt.show()"}]},{"title":"Creating a Final Visualization with Multiple Text Elements","body":["Creating a Final Visualization with Multiple Text Elements","In this final step, we will combine everything we've learned to create a comprehensive visualization that includes multiple text elements with different styles. This will demonstrate how text boxes can be used to enhance data storytelling.","Creating an Advanced Visualization","Let's create a more sophisticated plot that includes both our histogram and some additional visual elements. In a new cell, enter and run the following code:"],"code":[{"lang":"python","text":"# Create a figure with a larger size for our final visualization\nfig, ax = plt.subplots(figsize=(12, 8))\n\n# Plot the histogram with more bins and a different color\nn, bins, patches = ax.hist(x, bins=75, color='lightblue',\n                           edgecolor='darkblue', alpha=0.7)\n\n# Add title and labels with improved styling\nax.set_title('Distribution of Random Data with Statistical Annotations',\n             fontsize=18, fontweight='bold', pad=20)\nax.set_xlabel('Value', fontsize=14)\nax.set_ylabel('Frequency', fontsize=14)\n\n# Add grid for better readability\nax.grid(True, linestyle='--', alpha=0.7)\n\n# Mark the mean with a vertical line\nax.axvline(x=mu, color='red', linestyle='-', linewidth=2,\n           label=f'Mean: {mu:.2f}')\n\n# Mark one standard deviation range\nax.axvline(x=mu + sigma, color='green', linestyle='--', linewidth=1.5,\n           label=f'Mean + 1σ: {mu+sigma:.2f}')\nax.axvline(x=mu - sigma, color='green', linestyle='--', linewidth=1.5,\n           label=f'Mean - 1σ: {mu-sigma:.2f}')\n\n# Create a text box with statistics in the top left\nstats_box_props = dict(boxstyle='round', facecolor='lightyellow',\n                      alpha=0.8, edgecolor='gold', linewidth=2)\n\nstats_text = '\\n'.join((\n    r'$\\mathbf{Statistics:}$',\n    r'$\\mu=%.2f$ (mean)' % (mu,),\n    r'$\\mathrm{median}=%.2f$' % (median,),\n    r'$\\sigma=%.2f$ (std. dev.)' % (sigma,)\n))\n\nax.text(0.05, 0.95, stats_text, transform=ax.transAxes, fontsize=14,\n        verticalalignment='top', bbox=stats_box_props)\n\n# Add an informational text box in the top right\ninfo_box_props = dict(boxstyle='round4', facecolor='lightcyan',\n                     alpha=0.8, edgecolor='deepskyblue', linewidth=2)\n\ninfo_text = '\\n'.join((\n    r'$\\mathbf{About\\ Normal\\ Distributions:}$',\n    r'$\\bullet\\ 68\\%\\ of\\ data\\ within\\ 1\\sigma$',\n    r'$\\bullet\\ 95\\%\\ of\\ data\\ within\\ 2\\sigma$',"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Create a figure with a larger size for our final visualization\nfig, ax = plt.subplots(figsize=(12, 8))\n\n# Plot the histogram with more bins and a different color\nn, bins, patches = ax.hist(x, bins=75, color='lightblue',\n                           edgecolor='darkblue', alpha=0.7)\n\n# Add title and labels with improved styling\nax.set_title('Distribution of Random Data with Statistical Annotations',\n             fontsize=18, fontweight='bold', pad=20)\nax.set_xlabel('Value', fontsize=14)\nax.set_ylabel('Frequency', fontsize=14)\n\n# Add grid for better readability\nax.grid(True, linestyle='--', alpha=0.7)\n\n# Mark the mean with a vertical line\nax.axvline(x=mu, color='red', linestyle='-', linewidth=2,\n           label=f'Mean: {mu:.2f}')\n\n# Mark one standard deviation range\nax.axvline(x=mu + sigma, color='green', linestyle='--', linewidth=1.5,\n           label=f'Mean + 1σ: {mu+sigma:.2f}')\nax.axvline(x=mu - sigma, color='green', linestyle='--', linewidth=1.5,\n           label=f'Mean - 1σ: {mu-sigma:.2f}')\n\n# Create a text box with statistics in the top left\nstats_box_props = dict(boxstyle='round', facecolor='lightyellow',\n                      alpha=0.8, edgecolor='gold', linewidth=2)\n\nstats_text = '\\n'.join((\n    r'$\\mathbf{Statistics:}$',\n    r'$\\mu=%.2f$ (mean)' % (mu,),\n    r'$\\mathrm{median}=%.2f$' % (median,),\n    r'$\\sigma=%.2f$ (std. dev.)' % (sigma,)\n))\n\nax.text(0.05, 0.95, stats_text, transform=ax.transAxes, fontsize=14,\n        verticalalignment='top', bbox=stats_box_props)\n\n# Add an informational text box in the top right\ninfo_box_props = dict(boxstyle='round4', facecolor='lightcyan',\n                     alpha=0.8, edgecolor='deepskyblue', linewidth=2)\n\ninfo_text = '\\n'.join((\n    r'$\\mathbf{About\\ Normal\\ Distributions:}$',\n    r'$\\bullet\\ 68\\%\\ of\\ data\\ within\\ 1\\sigma$',\n    r'$\\bullet\\ 95\\%\\ of\\ data\\ within\\ 2\\sigma$',"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-creating-a-line-plot":{"intro":"In this lab, we will learn how to create a line plot using Python Matplotlib. A line plot is a way of displaying data points on a line. It is used to show the trend of a particular set of data over time.","steps":[{"title":"Importing Libraries","body":["First, we need to import the necessary libraries. We will be using the matplotlib.pyplot library to create our line plot."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Creating Data","body":["Next, we need to create some data that we will plot on our line. We will use NumPy to create some random data points for our line."],"code":[{"lang":"python","text":"x = np.linspace(0, 10)"}]},{"title":"Creating the Line Plot","body":["Now we can create our line plot using the plot() function from matplotlib.pyplot. We will plot 8 random lines using different colors from the Solarized Light color scheme."],"code":[{"lang":"python","text":"with plt.style.context('Solarize_Light2'):\n    plt.plot(x, np.sin(x) + x + np.random.randn(50))\n    plt.plot(x, np.sin(x) + 2 * x + np.random.randn(50))\n    plt.plot(x, np.sin(x) + 3 * x + np.random.randn(50))\n    plt.plot(x, np.sin(x) + 4 + np.random.randn(50))\n    plt.plot(x, np.sin(x) + 5 * x + np.random.randn(50))\n    plt.plot(x, np.sin(x) + 6 * x + np.random.randn(50))\n    plt.plot(x, np.sin(x) + 7 * x + np.random.randn(50))\n    plt.plot(x, np.sin(x) + 8 * x + np.random.randn(50))"}]},{"title":"Adding Labels and Title","body":["We can add labels and a title to our line plot using the xlabel(), ylabel(), and title() functions."],"code":[{"lang":"python","text":"plt.title('8 Random Lines - Line')\nplt.xlabel('x label', fontsize=14)\nplt.ylabel('y label', fontsize=14)"}]},{"title":"Displaying the Plot","body":["Finally, we can display our line plot using the show() function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-create-streamplot-with-matplotlib-in-python":{"intro":"This tutorial will guide you through the process of creating a streamplot using Matplotlib in Python. Streamplot is a 2D vector field that displays a set of streamlines. It is used to visualize fluid flow and other vector fields. In this tutorial, we will show you how to create a streamplot with varying density, color, and line width along with controlling the starting points of streamlines.","steps":[{"title":"Import Libraries","body":["Before starting, we need to import the required libraries. In this tutorial, we will be using Numpy and Matplotlib libraries. Numpy is used for numerical operations and Matplotlib is used for data visualization."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create Data","body":["We will create the data for our streamplot using the Numpy library. In this example, we will create a meshgrid with 100 points in both directions and calculate the U and V components of our vector field."],"code":[{"lang":"python","text":"w = 3\nY, X = np.mgrid[-w:w:100j, -w:w:100j]\nU = -1 - X**2 + Y\nV = 1 + X - Y**2\nspeed = np.sqrt(U**2 + V**2)"}]},{"title":"Varying Density","body":["In this step, we will create a streamplot with varying density. The density parameter controls the number of streamlines to be plotted. Higher values will result in more streamlines."],"code":[{"lang":"python","text":"plt.streamplot(X, Y, U, V, density=[0.5, 1])\nplt.title('Varying Density')\nplt.show()"}]},{"title":"Varying Color","body":["In this step, we will create a streamplot with varying color. The color parameter takes a 2D array that represents the magnitude of the vector field. Here, we are using the U component of the vector field as the color."],"code":[{"lang":"python","text":"strm = plt.streamplot(X, Y, U, V, color=U, linewidth=2, cmap='autumn')\nplt.colorbar(strm.lines)\nplt.title('Varying Color')\nplt.show()"}]},{"title":"Varying Line Width","body":["In this step, we will create a streamplot with varying line width. The linewidth parameter controls the width of the streamlines. Here, we are using the speed array that we calculated earlier to vary the linewidth."],"code":[{"lang":"python","text":"lw = 5*speed / speed.max()\nplt.streamplot(X, Y, U, V, density=0.6, color='k', linewidth=lw)\nplt.title('Varying Line Width')\nplt.show()"}]},{"title":"Controlling Starting Points","body":["In this step, we will create a streamplot with controlled starting points. The start_points parameter takes a 2D array that represents the starting points of the streamlines."],"code":[{"lang":"python","text":"seed_points = np.array([[-2, -1, 0, 1, 2, -1], [-2, -1, 0, 1, 2, 2]])\n\nstrm = plt.streamplot(X, Y, U, V, color=U, linewidth=2,\n                      cmap='autumn', start_points=seed_points.T)\nplt.colorbar(strm.lines)\nplt.title('Controlling Starting Points')\nplt.plot(seed_points[0], seed_points[1], 'bo')\nplt.xlim(-w, w)\nplt.ylim(-w, w)\nplt.show()"}]},{"title":"Streamplot with Masking","body":["In this step, we will create a streamplot with masking. We will create a mask and apply it to the U component of our vector field. The masked region will be skipped by the streamlines."],"code":[{"lang":"python","text":"mask = np.zeros(U.shape, dtype=bool)\nmask[40:60, 40:60] = True\nU[:20, :20] = np.nan\nU = np.ma.array(U, mask=mask)\n\nplt.streamplot(X, Y, U, V, color='r')\nplt.title('Streamplot with Masking')\nplt.imshow(~mask, extent=(-w, w, -w, w), alpha=0.5, cmap='gray', aspect='auto')\nplt.gca().set_aspect('equal')\nplt.show()"}]},{"title":"Unbroken Streamlines","body":["In this step, we will create a streamplot with unbroken streamlines. The broken_streamlines parameter controls whether the streamlines should be broken when they exceed the limit of lines within a single grid cell."],"code":[{"lang":"python","text":"plt.streamplot(X, Y, U, V, broken_streamlines=False)\nplt.title('Streamplot with Unbroken Streamlines')\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"plt.streamplot(X, Y, U, V, broken_streamlines=False)\nplt.title('Streamplot with Unbroken Streamlines')\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-create-polar-bar-chart-with-python-matplotli":{"intro":"In this lab, we will learn how to create a polar bar chart using Python Matplotlib library. We will create a chart that displays the distribution of values across different angles.","steps":[{"title":"Import necessary libraries","body":["We will start by importing the necessary libraries. In this lab, we will use Numpy and Matplotlib."],"code":[{"lang":"python","text":"import numpy as np\nimport matplotlib.pyplot as plt"}]},{"title":"Set random seed","body":["We will set a random seed so that the results will be reproducible."],"code":[{"lang":"python","text":"np.random.seed(19680801)"}]},{"title":"Define data","body":["We will define the data for the chart. We will generate 20 random values for radii and angles."],"code":[{"lang":"python","text":"N = 20\ntheta = np.linspace(0.0, 2 * np.pi, N, endpoint=False)\nradii = 10 * np.random.rand(N)\nwidth = np.pi / 4 * np.random.rand(N)\ncolors = plt.cm.viridis(radii / 10.)"}]},{"title":"Create a polar bar chart","body":["We will create a polar bar chart using the projection='polar' parameter."],"code":[{"lang":"python","text":"ax = plt.subplot(projection='polar')\nax.bar(theta, radii, width=width, bottom=0.0, color=colors, alpha=0.5)"}]},{"title":"Display the chart","body":["We will display the chart using the plt.show() function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-create-polar-line-plots-with-python":{"intro":"In this tutorial, we will learn how to create a line plot on a polar axis using Python Matplotlib. We will use the numpy library to generate the data and Matplotlib to plot the data.","steps":[{"title":"Import the necessary libraries","body":["Import the necessary libraries","The first step is to import the necessary libraries for this tutorial. We will use numpy to generate the data and matplotlib to plot the data."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Generate the data","body":["Next, we need to generate the data for the line plot. We will use the numpy library to generate an array of values for r and theta."],"code":[{"lang":"python","text":"r = np.arange(0, 2, 0.01)\ntheta = 2 * np.pi * r"}]},{"title":"Create the polar plot","body":["Now, we can create the polar plot using the subplot_kw parameter to specify the projection type as 'polar'."],"code":[{"lang":"python","text":"fig, ax = plt.subplots(subplot_kw={'projection': 'polar'})"}]},{"title":"Plot the line","body":["We can now plot the line on the polar axis using the plot function."],"code":[{"lang":"python","text":"ax.plot(theta, r)"}]},{"title":"Customize the plot","body":["To customize the plot, we can use the following methods:","• set_rmax to set the maximum value for r • set_rticks to set the tick values for r • set_rlabel_position to set the position of the radial labels","We can also add a title to the plot using the set_title method.","Finally, we can add a grid to the plot using the grid method."],"code":[{"lang":"python","text":"ax.set_rmax(2)\nax.set_rticks([0.5, 1, 1.5, 2])\nax.set_rlabel_position(-22.5)"},{"lang":"python","text":"ax.set_title(\"A line plot on a polar axis\", va='bottom')"},{"lang":"python","text":"ax.grid(True)"}]},{"title":"Display the plot","body":["To display the plot, we can use the show function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-error-bar-rendering-on-polar-axis":{"intro":"In data visualization, error bars are used to indicate the uncertainty or variability of data points. Matplotlib is a popular data visualization library in Python that provides built-in support for error bars. In this lab, we will learn how to create error bar plots in polar coordinates using Matplotlib.","steps":[{"title":"Import Necessary Libraries","body":["In this step, we will import the necessary libraries for creating error bar plots on polar axes."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create Data","body":["In this step, we will create the data for our error bar plot. We will use NumPy to create an array of theta values and an array of corresponding radius values."],"code":[{"lang":"python","text":"theta = np.arange(0, 2 * np.pi, np.pi / 4)\nr = theta / np.pi / 2 + 0.5"}]},{"title":"Create a Figure and Subplot","body":["In this step, we will create a figure and subplot for our error bar plot."],"code":[{"lang":"python","text":"fig = plt.figure(figsize=(10, 10))\nax = fig.add_subplot(projection='polar')"}]},{"title":"Create Error Bars","body":["In this step, we will create error bars on our polar axis. We will use the errorbar() function to create both radius and theta error bars."],"code":[{"lang":"python","text":"ax.errorbar(theta, r, xerr=0.25, yerr=0.1, capsize=7, fmt=\"o\", c=\"seagreen\")"}]},{"title":"Set Title and Show Plot","body":["In this step, we will set a title for our plot and show it using the show() function."],"code":[{"lang":"python","text":"ax.set_title(\"Pretty Polar Error Bars\")\nplt.show()"}]},{"title":"Create Overlapping Theta Error Bars","body":["Create Overlapping Theta Error Bars","In this step, we will create overlapping theta error bars to demonstrate how they can reduce readability of the output plot."],"code":[{"lang":"python","text":"fig = plt.figure(figsize=(10, 10))\nax = fig.add_subplot(projection='polar')\nax.errorbar(theta, r, xerr=5.25, yerr=0.1, capsize=7, fmt=\"o\", c=\"darkred\")\nax.set_title(\"Overlapping Theta Error Bars\")\nplt.show()"}]},{"title":"Create Large Radius Error Bars","body":["Create Large Radius Error Bars","In this step, we will create large radius error bars to demonstrate how they can lead to unwanted scale in the data, reducing the displayed range."],"code":[{"lang":"python","text":"fig = plt.figure(figsize=(10, 10))\nax = fig.add_subplot(projection='polar')\nax.errorbar(theta, r, xerr=0.25, yerr=10.1, capsize=7, fmt=\"o\", c=\"orangered\")\nax.set_title(\"Large Radius Error Bars\")\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig = plt.figure(figsize=(10, 10))\nax = fig.add_subplot(projection='polar')\nax.errorbar(theta, r, xerr=0.25, yerr=10.1, capsize=7, fmt=\"o\", c=\"orangered\")\nax.set_title(\"Large Radius Error Bars\")\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-polar-plot-with-legend":{"intro":"In this lab, you will learn how to create a polar plot with a legend using Python Matplotlib. Polar plots are used to plot data in polar coordinates, which is useful when working with directional data. Legends are used to explain the meaning of the different lines or markers on a plot.","steps":[{"title":"Import Libraries","body":["The first step is to import the necessary libraries. In this example, we will be using numpy and matplotlib."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create a Figure and Subplot","body":["Next, we need to create a figure and subplot for our plot. We will be using the projection parameter of add_subplot to create a polar plot."],"code":[{"lang":"python","text":"fig = plt.figure()\nax = fig.add_subplot(projection=\"polar\", facecolor=\"lightgoldenrodyellow\")"}]},{"title":"Create Data","body":["We need to create some data to plot on our polar plot. In this example, we will create two lines."],"code":[{"lang":"python","text":"r = np.linspace(0, 3, 301)\ntheta = 2 * np.pi * r"}]},{"title":"Plot Data","body":["Now we can plot our data using the plot function. We will create two lines using the data we created in step 3."],"code":[{"lang":"python","text":"ax.plot(theta, r, color=\"tab:orange\", lw=3, label=\"a line\")\nax.plot(0.5 * theta, r, color=\"tab:blue\", ls=\"--\", lw=3, label=\"another line\")"}]},{"title":"Customize Plot","body":["We can customize our plot by changing the grid color and adding a legend. In this example, we will move the legend slightly away from the center of the plot to avoid overlap."],"code":[{"lang":"python","text":"ax.tick_params(grid_color=\"palegoldenrod\")\nangle = np.deg2rad(67.5)\nax.legend(loc=\"lower left\",\n          bbox_to_anchor=(.5 + np.cos(angle)/2, .5 + np.sin(angle)/2))"}]},{"title":"Display Plot","body":["Finally, we can display our plot using the show function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-scatter-plot-on-polar-axis":{"intro":"In this tutorial, we will learn how to create scatter plots on a polar axis using Matplotlib in Python. A polar plot is a graphical representation of data that is displayed in polar coordinates. It is useful when the data is cyclical or circular in nature, such as data measured over time or direction.","steps":[{"title":"Import necessary libraries","body":["We need to import the Matplotlib and NumPy libraries to create the scatter plot on a polar axis. We will also set the random seed for reproducibility."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nnp.random.seed(19680801)"}]},{"title":"Generate random data","body":["We will generate random data for the scatter plot using NumPy. We will create 150 data points with random radius and angle values, and compute the area and color of each point."],"code":[{"lang":"python","text":"N = 150\nr = 2 * np.random.rand(N)\ntheta = 2 * np.pi * np.random.rand(N)\narea = 200 * r**2\ncolors = theta"}]},{"title":"Create a scatter plot on a polar axis","body":["Create a scatter plot on a polar axis","We will create a scatter plot on a polar axis using the plt.scatter() function. We will set the projection parameter to 'polar', and pass in the radius, angle, color, and area values as parameters."],"code":[{"lang":"python","text":"fig = plt.figure()\nax = fig.add_subplot(projection='polar')\nc = ax.scatter(theta, r, c=colors, s=area, cmap='hsv', alpha=0.75)"}]},{"title":"Create a scatter plot on a polar axis with offset origin","body":["Create a scatter plot on a polar axis with offset origin","We can create a scatter plot on a polar axis with an offset origin by setting the set_rorigin() and set_theta_zero_location() methods of the PolarAxes object. We will set the origin radius to -2.5 and the theta zero location to 'W' with an offset of 10."],"code":[{"lang":"python","text":"fig = plt.figure()\nax = fig.add_subplot(projection='polar')\nc = ax.scatter(theta, r, c=colors, s=area, cmap='hsv', alpha=0.75)\n\nax.set_rorigin(-2.5)\nax.set_theta_zero_location('W', offset=10)"}]},{"title":"Create a scatter plot on a polar axis confined to a sector","body":["Create a scatter plot on a polar axis confined to a sector","We can create a scatter plot on a polar axis confined to a sector by setting the set_thetamin() and set_thetamax() methods of the PolarAxes object. We will set the theta start and end limits to 45 and 135, respectively."],"code":[{"lang":"python","text":"fig = plt.figure()\nax = fig.add_subplot(projection='polar')\nc = ax.scatter(theta, r, c=colors, s=area, cmap='hsv', alpha=0.75)\n\nax.set_thetamin(45)\nax.set_thetamax(135)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig = plt.figure()\nax = fig.add_subplot(projection='polar')\nc = ax.scatter(theta, r, c=colors, s=area, cmap='hsv', alpha=0.75)\n\nax.set_thetamin(45)\nax.set_thetamax(135)"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-polygon-editor-for-cross-gui-apps":{"intro":"This lab is a step-by-step tutorial on how to build cross-GUI applications using Matplotlib event handling to interact with objects on the canvas. We will be creating a polygon editor that allows you to move, delete, and insert vertices.","steps":[{"title":"Import the Required Libraries","body":["We need to import the necessary libraries for the polygon editor."],"code":[{"lang":"python","text":"import numpy as np\nfrom matplotlib.artist import Artist\nfrom matplotlib.lines import Line2D"}]},{"title":"Create a Function to Calculate Distance","body":["Create a Function to Calculate Distance","We need to create a function that calculates the distance between a point and a line segment. This function will be used later to determine if a new vertex should be added to the polygon."],"code":[{"lang":"python","text":"def dist_point_to_segment(p, s0, s1):\n    \"\"\"\n    Get the distance from the point *p* to the segment (*s0*, *s1*), where\n    *p*, *s0*, *s1* are ``[x, y]`` arrays.\n    \"\"\"\n    s01 = s1 - s0\n    s0p = p - s0\n    if (s01 == 0).all():\n        return np.hypot(*s0p)\n    # Project onto segment, without going past segment ends.\n    p1 = s0 + np.clip((s0p @ s01) / (s01 @ s01), 0, 1) * s01\n    return np.hypot(*(p - p1))"}]},{"title":"Create the PolygonInteractor Class","body":["Create the PolygonInteractor Class","We need to create the PolygonInteractor class, which is the main class for the polygon editor. This class will handle all the interactions with the polygon, such as moving, deleting, and inserting vertices."],"code":[{"lang":"python","text":"class PolygonInteractor:\n    \"\"\"\n    A polygon editor.\n\n    Key-bindings\n\n      't' toggle vertex markers on and off.  When vertex markers are on,\n          you can move them, delete them\n\n      'd' delete the vertex under point\n\n      'i' insert a vertex at point.  You must be within epsilon of the\n          line connecting two existing vertices\n\n    \"\"\"\n\n    showverts = True\n    epsilon = 5  # max pixel distance to count as a vertex hit\n\n    def __init__(self, ax, poly):\n        if poly.figure is None:\n            raise RuntimeError('You must first add the polygon to a figure '\n                               'or canvas before defining the interactor')\n        self.ax = ax\n        canvas = poly.figure.canvas\n        self.poly = poly\n\n        x, y = zip(*self.poly.xy)\n        self.line = Line2D(x, y,\n                           marker='o', markerfacecolor='r',\n                           animated=True)\n        self.ax.add_line(self.line)\n\n        self.cid = self.poly.add_callback(self.poly_changed)\n        self._ind = None  # the active vert\n\n        canvas.mpl_connect('draw_event', self.on_draw)\n        canvas.mpl_connect('button_press_event', self.on_button_press)\n        canvas.mpl_connect('key_press_event', self.on_key_press)\n        canvas.mpl_connect('button_release_event', self.on_button_release)\n        canvas.mpl_connect('motion_notify_event', self.on_mouse_move)\n        self.canvas = canvas\n\n    def on_draw(self, event):\n        self.background = self.canvas.copy_from_bbox(self.ax.bbox)\n        self.ax.draw_artist(self.poly)\n        self.ax.draw_artist(self.line)\n        # do not need to blit here, this will fire before the screen is"}]},{"title":"Create the Polygon","body":["We need to create the polygon that we will be editing using the Polygon class."],"code":[{"lang":"python","text":"theta = np.arange(0, 2*np.pi, 0.1)\nr = 1.5\n\nxs = r * np.cos(theta)\nys = r * np.sin(theta)\n\npoly = Polygon(np.column_stack([xs, ys]), animated=True)"}]},{"title":"Create the Plot","body":["We need to create the plot and add the polygon to it."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.add_patch(poly)\np = PolygonInteractor(ax, poly)\n\nax.set_title('Click and drag a point to move it')\nax.set_xlim((-2, 2))\nax.set_ylim((-2, 2))\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, ax = plt.subplots()\nax.add_patch(poly)\np = PolygonInteractor(ax, poly)\n\nax.set_title('Click and drag a point to move it')\nax.set_xlim((-2, 2))\nax.set_ylim((-2, 2))\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-select-indices-using-polygon-selector":{"intro":"This lab demonstrates how to use the Polygon Selector tool in Matplotlib to select indices from a collection. The Polygon Selector tool allows the user to select points on a graph by drawing a polygon around them. The selected points are then highlighted while the unselected points are faded out. The indices of the selected points are saved in an array, which can then be used for further analysis.","steps":[{"title":"Import Libraries","body":["In this step, we will import the necessary libraries for this lab. We will be using numpy and matplotlib for data manipulation and visualization."],"code":[{"lang":"python","text":"import numpy as np\nimport matplotlib.pyplot as plt\nfrom matplotlib.path import Path\nfrom matplotlib.widgets import PolygonSelector"}]},{"title":"Create Data","body":["In this step, we will create some data to visualize. We will create a scatter plot of points on a grid."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\ngrid_size = 5\ngrid_x = np.tile(np.arange(grid_size), grid_size)\ngrid_y = np.repeat(np.arange(grid_size), grid_size)\npts = ax.scatter(grid_x, grid_y)"}]},{"title":"Define Selector Class","body":["In this step, we will define a class that will allow us to select points from the scatter plot using the Polygon Selector tool. This class will save the indices of the selected points in an array."],"code":[{"lang":"python","text":"class SelectFromCollection:\n    \"\"\"\n    Select indices from a matplotlib collection using `PolygonSelector`.\n\n    Selected indices are saved in the `ind` attribute. This tool fades out the\n    points that are not part of the selection (i.e., reduces their alpha\n    values). If your collection has alpha < 1, this tool will permanently\n    alter the alpha values.\n\n    Note that this tool selects collection objects based on their *origins*\n    (i.e., `offsets`).\n\n    Parameters\n    ----------\n    ax : `~matplotlib.axes.Axes`\n        Axes to interact with.\n    collection : `matplotlib.collections.Collection` subclass\n        Collection you want to select from.\n    alpha_other : 0 <= float <= 1\n        To highlight a selection, this tool sets all selected points to an\n        alpha value of 1 and non-selected points to *alpha_other*.\n    \"\"\"\n\n    def __init__(self, ax, collection, alpha_other=0.3):\n        self.canvas = ax.figure.canvas\n        self.collection = collection\n        self.alpha_other = alpha_other\n\n        self.xys = collection.get_offsets()\n        self.Npts = len(self.xys)\n\n        # Ensure that we have separate colors for each object\n        self.fc = collection.get_facecolors()\n        if len(self.fc) == 0:\n            raise ValueError('Collection must have a facecolor')\n        elif len(self.fc) == 1:\n            self.fc = np.tile(self.fc, (self.Npts, 1))\n\n        self.poly = PolygonSelector(ax, self.onselect, draw_bounding_box=True)\n        self.ind = []\n\n    def onselect(self, verts):\n        path = Path(verts)\n        self.ind = np.nonzero(path.contains_points(self.xys))[0]\n        self.fc[:, -1] = self.alpha_other\n        self.fc[self.ind, -1] = 1\n        self.collection.set_facecolors(self.fc)\n        self.canvas.draw_idle()"}]},{"title":"Create Selector Object","body":["In this step, we will create an instance of the Selector class that we defined in Step 3. This will allow us to select points from the scatter plot using the Polygon Selector tool."],"code":[{"lang":"python","text":"selector = SelectFromCollection(ax, pts)"}]},{"title":"Select Points","body":["In this step, we will select points from the scatter plot using the Polygon Selector tool. We can select points by drawing a polygon around them. The selected points will be highlighted while the unselected points will be faded out."],"code":[{"lang":"python","text":"print(\"Select points in the figure by enclosing them within a polygon.\")\nprint(\"Press the 'esc' key to start a new polygon.\")\nprint(\"Try holding the 'shift' key to move all of the vertices.\")\nprint(\"Try holding the 'ctrl' key to move a single vertex.\")\nplt.show()"}]},{"title":"Disconnect Selector Object","body":["In this step, we will disconnect the Selector object to release the resources used by the Polygon Selector tool."],"code":[{"lang":"python","text":"selector.disconnect()"}]},{"title":"Print Selected Points","body":["In this step, we will print the coordinates of the selected points."],"code":[{"lang":"python","text":"print('\\nSelected points:')\nprint(selector.xys[selector.ind])"}]}],"commands":[],"reference":[{"path":"reference.py","text":"print('\\nSelected points:')\nprint(selector.xys[selector.ind])"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-creating-a-polygon-in-matplotlib":{"intro":"Matplotlib is a Python library used for data visualization. In this lab, we will be using Matplotlib to create a polygon programmatically or interactively. The polygon can be used to highlight a region of interest or to mask out a certain area of a plot.","steps":[{"title":"Import Required Libraries","body":["Before we start working with Matplotlib, we need to import the necessary libraries. We will be using matplotlib.pyplot and matplotlib.widgets in this lab."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom matplotlib.widgets import PolygonSelector"}]},{"title":"Create a Polygon Programmatically","body":["Create a Polygon Programmatically","To create a polygon programmatically, we need to create a Figure object and an Axes object. Then, we can create a PolygonSelector object and add vertices to it. Finally, we can plot the polygon on the Axes."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nselector = PolygonSelector(ax, lambda *args: None)\n\n# Add three vertices\nselector.verts = [(0.1, 0.4), (0.5, 0.9), (0.3, 0.2)]\n\n# Plot the polygon\nax.add_patch(plt.Polygon(selector.verts, alpha=0.3))\nplt.show()"}]},{"title":"Create a Polygon Interactively","body":["Create a Polygon Interactively"],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nselector = PolygonSelector(ax, lambda *args: None)\n\nprint(\"Click on the figure to create a polygon.\")\nprint(\"Press the 'esc' key to start a new polygon.\")\nprint(\"Try holding the 'shift' key to move all of the vertices.\")\nprint(\"Try holding the 'ctrl' key to move a single vertex.\")\n\nplt.show()"}]},{"title":"Putting It All Together","body":["Let's create a complete example that includes both creating a polygon programmatically and interactively."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom matplotlib.widgets import PolygonSelector\n\n# Create a figure and axes\nfig, (ax1, ax2) = plt.subplots(ncols=2, figsize=(10, 5))\n\n# Create a PolygonSelector object and add vertices\nselector1 = PolygonSelector(ax1, lambda *args: None)\nselector1.verts = [(0.1, 0.4), (0.5, 0.9), (0.3, 0.2)]\n\n# Plot the polygon\nax1.add_patch(plt.Polygon(selector1.verts, alpha=0.3))\n\n# Create another PolygonSelector object for interactive creation\nselector2 = PolygonSelector(ax2, lambda *args: None)\n\nprint(\"Click on the figure to create a polygon.\")\nprint(\"Press the 'esc' key to start a new polygon.\")\nprint(\"Try holding the 'shift' key to move all of the vertices.\")\nprint(\"Try holding the 'ctrl' key to move a single vertex.\")\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"import matplotlib.pyplot as plt\nfrom matplotlib.widgets import PolygonSelector\n\n# Create a figure and axes\nfig, (ax1, ax2) = plt.subplots(ncols=2, figsize=(10, 5))\n\n# Create a PolygonSelector object and add vertices\nselector1 = PolygonSelector(ax1, lambda *args: None)\nselector1.verts = [(0.1, 0.4), (0.5, 0.9), (0.3, 0.2)]\n\n# Plot the polygon\nax1.add_patch(plt.Polygon(selector1.verts, alpha=0.3))\n\n# Create another PolygonSelector object for interactive creation\nselector2 = PolygonSelector(ax2, lambda *args: None)\n\nprint(\"Click on the figure to create a polygon.\")\nprint(\"Press the 'esc' key to start a new polygon.\")\nprint(\"Try holding the 'shift' key to move all of the vertices.\")\nprint(\"Try holding the 'ctrl' key to move a single vertex.\")\n\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-create-3d-polygon-fills-for-line-graphs":{"intro":"In this tutorial, we will learn how to create polygons which fill the space under a line graph in a 3D plot using Python's Matplotlib library. The polygons will be semi-transparent, creating a sort of 'jagged stained glass' effect.","steps":[{"title":"Import the Required Libraries","body":["We will begin by importing the necessary libraries."],"code":[{"lang":"python","text":"import math\nimport matplotlib.pyplot as plt\nimport numpy as np\nfrom matplotlib.collections import PolyCollection"}]},{"title":"Define the Polygon Under Graph Function","body":["Define the Polygon Under Graph Function","Next, we define a function polygon_under_graph(x, y) which constructs the vertex list that defines the polygon filling the space under the (x, y) line graph. This function assumes that x is in ascending order."],"code":[{"lang":"python","text":"def polygon_under_graph(x, y):\n    \"\"\"\n    Construct the vertex list which defines the polygon filling the space under\n    the (x, y) line graph. This assumes x is in ascending order.\n    \"\"\"\n    return [(x[0], 0.), *zip(x, y), (x[-1], 0.)]"}]},{"title":"Create the 3D Plot","body":["We will now create a 3D plot using Matplotlib."],"code":[{"lang":"python","text":"ax = plt.figure().add_subplot(projection='3d')"}]},{"title":"Define the x and lambda Arrays","body":["Define the x and lambda Arrays","We define the x and lambda arrays using the linspace and range functions respectively."],"code":[{"lang":"python","text":"x = np.linspace(0., 10., 31)\nlambdas = range(1, 9)"}]},{"title":"Compute the Vertices and Facecolors","body":["Compute the Vertices and Facecolors","We compute the vertices and facecolors using the vectorize and colormaps functions from Matplotlib."],"code":[{"lang":"python","text":"# verts[i] is a list of (x, y) pairs defining polygon i.\ngamma = np.vectorize(math.gamma)\nverts = [polygon_under_graph(x, l**x * np.exp(-l) / gamma(x + 1))\n         for l in lambdas]\nfacecolors = plt.colormaps['viridis_r'](np.linspace(0, 1, len(verts)))"}]},{"title":"Create the Polygons and Add to the Plot","body":["Create the Polygons and Add to the Plot","We create the polygons using the PolyCollection function from Matplotlib and add them to the plot."],"code":[{"lang":"python","text":"poly = PolyCollection(verts, facecolors=facecolors, alpha=.7)\nax.add_collection3d(poly, zs=lambdas, zdir='y')"}]},{"title":"Set the Plot Limits and Labels","body":["Set the Plot Limits and Labels","Finally, we set the plot limits and labels using the set function."],"code":[{"lang":"python","text":"ax.set(xlim=(0, 10), ylim=(1, 9), zlim=(0, 0.35),\n       xlabel='x', ylabel=r'$\\lambda$', zlabel='probability')"}]},{"title":"Show the Plot","body":["We display the plot using the show function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-game-pong":{"intro":"In this lab, you will learn how to create an interactive game of Pong using Matplotlib. Pong is a classic arcade game that involves two players hitting a ball back and forth across a virtual playing field using paddles. This lab will guide you through the process of building your own Pong game using Python and Matplotlib.","steps":[{"title":"Install Matplotlib","body":[],"code":[{"lang":"python","text":"pip install matplotlib"}]},{"title":"Import Libraries","body":["The first thing we need to do is import the necessary libraries. We will be using time, numpy, and matplotlib."],"code":[{"lang":"python","text":"import time\nimport matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Define the Pad and Puck Classes","body":["Define the Pad and Puck Classes","Next, we need to define the Pad and Puck classes. The Pad class represents the paddles used by the players, while the Puck class represents the ball."],"code":[{"lang":"python","text":"class Pad:\n    def __init__(self, disp, x, y, type='l'):\n        self.disp = disp\n        self.x = x\n        self.y = y\n        self.w = .3\n        self.score = 0\n        self.xoffset = 0.3\n        self.yoffset = 0.1\n        if type == 'r':\n            self.xoffset *= -1.0\n\n        if type == 'l' or type == 'r':\n            self.signx = -1.0\n            self.signy = 1.0\n        else:\n            self.signx = 1.0\n            self.signy = -1.0\n\n    def contains(self, loc):\n        return self.disp.get_bbox().contains(loc.x, loc.y)\n\n\nclass Puck:\n    def __init__(self, disp, pad, field):\n        self.vmax = .2\n        self.disp = disp\n        self.field = field\n        self._reset(pad)\n\n    def _reset(self, pad):\n        self.x = pad.x + pad.xoffset\n        if pad.y < 0:\n            self.y = pad.y + pad.yoffset\n        else:\n            self.y = pad.y - pad.yoffset\n        self.vx = pad.x - self.x\n        self.vy = pad.y + pad.w/2 - self.y\n        self._speedlimit()\n        self._slower()\n        self._slower()\n\n    def update(self, pads):\n        self.x += self.vx\n        self.y += self.vy\n        for pad in pads:\n            if pad.contains(self):\n                self.vx *= 1.2 * pad.signx"}]},{"title":"Define the Game Class","body":["Now that we have the Pad and Puck classes defined, we can move on to defining the Game class. This class will be responsible for handling the game logic and drawing the game on the screen."],"code":[{"lang":"python","text":"class Game:\n    def __init__(self, ax):\n        # create the initial line\n        self.ax = ax\n        ax.xaxis.set_visible(False)\n        ax.set_xlim([0, 7])\n        ax.yaxis.set_visible(False)\n        ax.set_ylim([-1, 1])\n        pad_a_x = 0\n        pad_b_x = .50\n        pad_a_y = pad_b_y = .30\n        pad_b_x += 6.3\n\n        # pads\n        pA, = self.ax.barh(pad_a_y, .2,\n                           height=.3, color='k', alpha=.5, edgecolor='b',\n                           lw=2, label=\"Player B\",\n                           animated=True)\n        pB, = self.ax.barh(pad_b_y, .2,\n                           height=.3, left=pad_b_x, color='k', alpha=.5,\n                           edgecolor='r', lw=2, label=\"Player A\",\n                           animated=True)\n\n        # distractors\n        self.x = np.arange(0, 2.22*np.pi, 0.01)\n        self.line, = self.ax.plot(self.x, np.sin(self.x), \"r\",\n                                  animated=True, lw=4)\n        self.line2, = self.ax.plot(self.x, np.cos(self.x), \"g\",\n                                   animated=True, lw=4)\n        self.line3, = self.ax.plot(self.x, np.cos(self.x), \"g\",\n                                   animated=True, lw=4)\n        self.line4, = self.ax.plot(self.x, np.cos(self.x), \"r\",\n                                   animated=True, lw=4)\n\n        # center line\n        self.centerline, = self.ax.plot([3.5, 3.5], [1, -1], 'k',\n                                        alpha=.5, animated=True, lw=8)\n\n        # puck (s)\n        self.puckdisp = self.ax.scatter([1], [1], label='_nolegend_',\n                                        s=200, c='g',\n                                        alpha=.9, animated=True)\n\n        self.canvas = self.ax.figure.canvas\n        self.background = None\n        self.cnt = 0\n        self.distract = True\n        self.res = 100.0"}]},{"title":"Create the Game Animation","body":["Now that we have the Game class defined, we can create the game animation by instantiating a Game object and calling its draw() method in a loop."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\ncanvas = ax.figure.canvas\nanimation = Game(ax)\n\n# disable the default key bindings\nif fig.canvas.manager.key_press_handler_id is not None:\n    canvas.mpl_disconnect(fig.canvas.manager.key_press_handler_id)\n\n\n# reset the blitting background on redraw\ndef on_redraw(event):\n    animation.background = None\n\n\n# bootstrap after the first draw\ndef start_anim(event):\n    canvas.mpl_disconnect(start_anim.cid)\n\n    start_anim.timer.add_callback(animation.draw)\n    start_anim.timer.start()\n    canvas.mpl_connect('draw_event', on_redraw)\n\n\nstart_anim.cid = canvas.mpl_connect('draw_event', start_anim)\nstart_anim.timer = animation.canvas.new_timer(interval=1)\n\ntstart = time.time()\n\nplt.show()\nprint('FPS: %f' % (animation.cnt/(time.time() - tstart)))"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, ax = plt.subplots()\ncanvas = ax.figure.canvas\nanimation = Game(ax)\n\n# disable the default key bindings\nif fig.canvas.manager.key_press_handler_id is not None:\n    canvas.mpl_disconnect(fig.canvas.manager.key_press_handler_id)\n\n\n# reset the blitting background on redraw\ndef on_redraw(event):\n    animation.background = None\n\n\n# bootstrap after the first draw\ndef start_anim(event):\n    canvas.mpl_disconnect(start_anim.cid)\n\n    start_anim.timer.add_callback(animation.draw)\n    start_anim.timer.start()\n    canvas.mpl_connect('draw_event', on_redraw)\n\n\nstart_anim.cid = canvas.mpl_connect('draw_event', start_anim)\nstart_anim.timer = animation.canvas.new_timer(interval=1)\n\ntstart = time.time()\n\nplt.show()\nprint('FPS: %f' % (animation.cnt/(time.time() - tstart)))"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-multivariate-normal-distribution-visualizati":{"intro":"This lab explores various normalizations on a multivariate normal distribution using Python Matplotlib. In this lab, you will learn about linear normalization, power law normalization, and how to use Matplotlib to visualize the multivariate normal distribution.","steps":[{"title":"Import Libraries","body":["In this step, you need to import the necessary libraries which are Matplotlib, NumPy, and Multivariate_normal from NumPy.random."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom numpy.random import multivariate_normal"}]},{"title":"Set Random State","body":["In this step, you need to set the random state for reproducibility."],"code":[{"lang":"python","text":"np.random.seed(19680801)"}]},{"title":"Create Data","body":["In this step, you need to create data using multivariate_normal(). This function generates a random sample from a multivariate normal distribution."],"code":[{"lang":"python","text":"data = np.vstack([\n    multivariate_normal([10, 10], [[3, 2], [2, 3]], size=100000),\n    multivariate_normal([30, 20], [[3, 1], [1, 3]], size=1000)\n])"}]},{"title":"Create Histogram","body":["In this step, you need to create a histogram using hist2d(). The hist2d() function is used to create a two-dimensional histogram."],"code":[{"lang":"python","text":"plt.hist2d(data[:, 0], data[:, 1], bins=100)"}]},{"title":"Create Power Law Normalization","body":["Create Power Law Normalization","In this step, you need to create power law normalization using PowerNorm()."],"code":[{"lang":"python","text":"plt.hist2d(data[:, 0], data[:, 1], bins=100, norm=mcolors.PowerNorm(gamma))"}]},{"title":"Create Subplots","body":["In this step, you need to create subplots using subplots()."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(nrows=2, ncols=2)"}]},{"title":"Create Linear Normalization","body":["In this step, you need to create linear normalization."],"code":[{"lang":"python","text":"axs[0, 0].hist2d(data[:, 0], data[:, 1], bins=100)"}]},{"title":"Create Power Law Normalization","body":["Create Power Law Normalization","In this step, you need to create power law normalization with different gamma values."],"code":[{"lang":"python","text":"for ax, gamma in zip(axs.flat[1:], gammas):\n    ax.hist2d(data[:, 0], data[:, 1], bins=100, norm=mcolors.PowerNorm(gamma))"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-print-stdout-sgskip":{"intro":"Matplotlib is a Python library used for plotting graphs and data visualizations. In this lab, you will learn how to use Matplotlib to create and save a simple line plot.","steps":[{"title":"Import necessary libraries","body":["To use Matplotlib, we first need to import it along with other necessary libraries. The code for this is shown below:"],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt"}]},{"title":"Create a dataset","body":["Next, we need to create a dataset to plot. In this example, we will use a simple list of numbers. The code for this is shown below:"],"code":[{"lang":"python","text":"data = [1, 2, 3, 4, 5]"}]},{"title":"Create a plot","body":["Now that we have our data, we can create a plot. In this example, we will create a simple line plot using the plot() function. The code for this is shown below:"],"code":[{"lang":"python","text":"plt.plot(data)"}]},{"title":"Customize the plot","body":["We can customize the plot by adding a title, labels for the x-axis and y-axis, and a grid. The code for this is shown below:"],"code":[{"lang":"python","text":"plt.title(\"My Plot\")\nplt.xlabel(\"X-axis Label\")\nplt.ylabel(\"Y-axis Label\")\nplt.grid(True)"}]},{"title":"Save the plot","body":["Finally, we can save the plot to a file using the savefig() function. In this example, we will save the plot as a PNG file. The code for this is shown below:"],"code":[{"lang":"python","text":"plt.savefig(\"my_plot.png\")"}]}],"commands":[],"reference":[{"path":"reference.py","text":"plt.savefig(\"my_plot.png\")"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-3d-plot-projection-types":{"intro":"This lab demonstrates the different camera projections for 3D plots, and the effects of changing the focal length for a perspective projection using Python Matplotlib.","steps":[{"title":"Import Libraries","body":["First, import the necessary libraries, including Matplotlib and Axes3D from mpl_toolkits.mplot3d."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom mpl_toolkits.mplot3d import axes3d"}]},{"title":"Get Data","body":["Get the test data for the 3D plot."],"code":[{"lang":"python","text":"X, Y, Z = axes3d.get_test_data(0.05)"}]},{"title":"Create a Figure with Subplots","body":["Create a figure with three subplots using plt.subplots."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(1, 3, subplot_kw={'projection': '3d'})"}]},{"title":"Plot the Data","body":["Plot the data on each of the three subplots using plot_wireframe."],"code":[{"lang":"python","text":"for ax in axs:\n    ax.plot_wireframe(X, Y, Z, rstride=10, cstride=10)"}]},{"title":"Set the Orthographic Projection","body":["Set the Orthographic Projection","Set the first subplot to use an orthographic projection with a FOV of 0 degrees and a focal_length of infinity."],"code":[{"lang":"python","text":"axs[0].set_proj_type('ortho')  # FOV = 0 deg\naxs[0].set_title(\"'ortho'\\nfocal_length = ∞\", fontsize=10)"}]},{"title":"Set the Perspective Projections","body":["Set the Perspective Projections","Set the second subplot to use a perspective projection with the default FOV of 90 degrees and a focal_length of 1.","Set the third subplot to use a perspective projection with a FOV of 157.4 degrees and a focal_length of 0.2."],"code":[{"lang":"python","text":"axs[1].set_proj_type('persp')  # FOV = 90 deg\naxs[1].set_title(\"'persp'\\nfocal_length = 1 (default)\", fontsize=10)"},{"lang":"python","text":"axs[2].set_proj_type('persp', focal_length=0.2)  # FOV = 157.4 deg\naxs[2].set_title(\"'persp'\\nfocal_length = 0.2\", fontsize=10)"}]},{"title":"Show the Plot","body":["Display the plot using plt.show()."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-psd-plotting":{"intro":"This tutorial will guide you through the process of plotting the Power Spectral Density (PSD) using the Matplotlib library in Python. The PSD is a plot commonly used in the field of signal processing. NumPy has many useful libraries for computing a PSD, and we will show a few examples of how this can be accomplished and visualized with Matplotlib.","steps":[{"title":"Plot a basic PSD","body":["First, we will plot a basic PSD using random data. We will create a time series, add noise, and then plot the PSD using the psd function from the matplotlib.mlab library."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nimport matplotlib.mlab as mlab\n\nnp.random.seed(19680801)\ndt = 0.01\nt = np.arange(0, 10, dt)\nnse = np.random.randn(len(t))\nr = np.exp(-t / 0.05)\ncnse = np.convolve(nse, r) * dt\ncnse = cnse[:len(t)]\ns = 0.1 * np.sin(2 * np.pi * t) + cnse\n\nfig, (ax0, ax1) = plt.subplots(2, 1)\nax0.plot(t, s)\nax1.psd(s, 512, 1 / dt)\n\nplt.show()"}]},{"title":"Compare with equivalent MATLAB code","body":["Compare with equivalent MATLAB code","We can compare the previous code with the equivalent MATLAB code to accomplish the same thing:"],"code":[{"lang":"python","text":"dt = 0.01;\nt = [0:dt:10];\nnse = randn(size(t));\nr = exp(-t/0.05);\ncnse = conv(nse, r)*dt;\ncnse = cnse(1:length(t));\ns = 0.1*sin(2*pi*t) + cnse;\n\nsubplot(211)\nplot(t, s)\nsubplot(212)\npsd(s, 512, 1/dt)"}]},{"title":"Plot PSD with different amounts of padding","body":["Plot PSD with different amounts of padding","Next, we will plot the PSD with different amounts of zero padding. This uses the entire time series at once."],"code":[{"lang":"python","text":"dt = np.pi / 100.\nfs = 1. / dt\nt = np.arange(0, 8, dt)\ny = 10. * np.sin(2 * np.pi * 4 * t) + 5. * np.sin(2 * np.pi * 4.25 * t)\ny = y + np.random.randn(*t.shape)\n\nfig, axs = plt.subplot_mosaic([\n    ['signal', 'signal', 'signal'],\n    ['zero padding', 'block size', 'overlap'],\n], layout='constrained')\n\naxs['signal'].plot(t, y)\naxs['signal'].set_xlabel('time [s]')\naxs['signal'].set_ylabel('signal')\n\naxs['zero padding'].psd(y, NFFT=len(t), pad_to=len(t), Fs=fs)\naxs['zero padding'].psd(y, NFFT=len(t), pad_to=len(t) * 2, Fs=fs)\naxs['zero padding'].psd(y, NFFT=len(t), pad_to=len(t) * 4, Fs=fs)\n\naxs['block size'].psd(y, NFFT=len(t), pad_to=len(t), Fs=fs)\naxs['block size'].psd(y, NFFT=len(t) // 2, pad_to=len(t), Fs=fs)\naxs['block size'].psd(y, NFFT=len(t) // 4, pad_to=len(t), Fs=fs)\naxs['block size'].set_ylabel('')\n\naxs['overlap'].psd(y, NFFT=len(t) // 2, pad_to=len(t), noverlap=0, Fs=fs)\naxs['overlap'].psd(y, NFFT=len(t) // 2, pad_to=len(t),\n                   noverlap=int(0.025 * len(t)), Fs=fs)\naxs['overlap'].psd(y, NFFT=len(t) // 2, pad_to=len(t),\n                   noverlap=int(0.1 * len(t)), Fs=fs)\naxs['overlap'].set_ylabel('')\naxs['overlap'].set_title('overlap')\n\nfor title, ax in axs.items():\n    if title == 'signal':\n        continue\n\n    ax.set_title(title)\n    ax.sharex(axs['zero padding'])\n    ax.sharey(axs['zero padding'])\n\nplt.show()"}]},{"title":"Plot PSD of a complex signal","body":["Finally, we will plot the PSD of a complex signal to demonstrate that complex PSD's work properly."],"code":[{"lang":"python","text":"prng = np.random.RandomState(19680801)\nfs = 1000\nt = np.linspace(0, 0.3, 301)\nA = np.array([2, 8]).reshape(-1, 1)\nf = np.array([150, 140]).reshape(-1, 1)\nxn = (A * np.exp(2j * np.pi * f * t)).sum(axis=0) + 5 * prng.randn(*t.shape)\n\nfig, (ax0, ax1) = plt.subplots(ncols=2, layout='constrained')\n\nyticks = np.arange(-50, 30, 10)\nyrange = (yticks[0], yticks[-1])\nxticks = np.arange(-500, 550, 200)\n\nax0.psd(xn, NFFT=301, Fs=fs, window=mlab.window_none, pad_to=1024,\n        scale_by_freq=True)\nax0.set_title('Periodogram')\nax0.set_yticks(yticks)\nax0.set_xticks(xticks)\nax0.grid(True)\nax0.set_ylim(yrange)\n\nax1.psd(xn, NFFT=150, Fs=fs, window=mlab.window_none, pad_to=512, noverlap=75,\n        scale_by_freq=True)\nax1.set_title('Welch')\nax1.set_xticks(xticks)\nax1.set_yticks(yticks)\nax1.set_ylabel('')\nax1.grid(True)\nax1.set_ylim(yrange)\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"prng = np.random.RandomState(19680801)\nfs = 1000\nt = np.linspace(0, 0.3, 301)\nA = np.array([2, 8]).reshape(-1, 1)\nf = np.array([150, 140]).reshape(-1, 1)\nxn = (A * np.exp(2j * np.pi * f * t)).sum(axis=0) + 5 * prng.randn(*t.shape)\n\nfig, (ax0, ax1) = plt.subplots(ncols=2, layout='constrained')\n\nyticks = np.arange(-50, 30, 10)\nyrange = (yticks[0], yticks[-1])\nxticks = np.arange(-500, 550, 200)\n\nax0.psd(xn, NFFT=301, Fs=fs, window=mlab.window_none, pad_to=1024,\n        scale_by_freq=True)\nax0.set_title('Periodogram')\nax0.set_yticks(yticks)\nax0.set_xticks(xticks)\nax0.grid(True)\nax0.set_ylim(yrange)\n\nax1.psd(xn, NFFT=150, Fs=fs, window=mlab.window_none, pad_to=512, noverlap=75,\n        scale_by_freq=True)\nax1.set_title('Welch')\nax1.set_xticks(xticks)\nax1.set_yticks(yticks)\nax1.set_ylabel('')\nax1.grid(True)\nax1.set_ylim(yrange)\n\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-pylab-with-gtk3-sgskip":{"intro":"In this lab, we will learn how to use the Matplotlib library to create and modify figure windows. We will also explore how to customize the GUI by accessing the underlying GTK widgets.","steps":[{"title":"Import Libraries","body":["First, we need to import the necessary libraries. We will be using Matplotlib, GTK3, and the Gtk module from the gi.repository."],"code":[{"lang":"python","text":"import matplotlib\nmatplotlib.use('GTK3Agg')  # or 'GTK3Cairo'\nimport gi\nimport matplotlib.pyplot as plt\ngi.require_version('Gtk', '3.0')\nfrom gi.repository import Gtk"}]},{"title":"Create Figure and Axis","body":["Next, we will create a figure and axis using the subplots() method. We will then plot two lines on the axis and add a legend to distinguish them."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.plot([1, 2, 3], 'ro-', label='easy as 1 2 3')\nax.plot([1, 4, 9], 'gs--', label='easy as 1 2 3 squared')\nax.legend()"}]},{"title":"Access Toolbar and VBox","body":["We will access the toolbar and vbox attributes of the figure canvas manager using the manager.toolbar and manager.vbox methods, respectively."],"code":[{"lang":"python","text":"manager = fig.canvas.manager\ntoolbar = manager.toolbar\nvbox = manager.vbox"}]},{"title":"Add Button to Toolbar","body":[],"code":[{"lang":"python","text":"button = Gtk.Button(label='Click me')\nbutton.show()\nbutton.connect('clicked', lambda button: print('hi mom'))\n\ntoolitem = Gtk.ToolItem()\ntoolitem.show()\ntoolitem.set_tooltip_text('Click me for fun and profit')\ntoolitem.add(button)\n\npos = 8  # where to insert this in the toolbar\ntoolbar.insert(toolitem, pos)"}]},{"title":"Add Label to VBox","body":["We will add a label to the vbox to display the x,y coordinates of the mouse when it is dragged over the axis. First, we create a label with some text and add it to the vbox."],"code":[{"lang":"python","text":"label = Gtk.Label()\nlabel.set_markup('Drag mouse over axes for position')\nlabel.show()\nvbox.pack_start(label, False, False, 0)"}]},{"title":"Update Label Text on Mouse Movement","body":["Update Label Text on Mouse Movement","We will update the label text to display the x,y coordinates of the mouse when it is dragged over the axis. We create a function to update the label text and connect it to the motion_notify_event using the mpl_connect() method."],"code":[{"lang":"python","text":"def update(event):\n    if event.xdata is None:\n        label.set_markup('Drag mouse over axes for position')\n    else:\n        label.set_markup(\n            f'<span color=\"#ef0000\">x,y=({event.xdata}, {event.ydata})</span>')\n\nfig.canvas.mpl_connect('motion_notify_event', update)"}]},{"title":"Display the Plot","body":["Finally, we display the plot using the show() method."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-pylab-with-gtk4-sgskip":{"intro":"In this lab, we will learn how to use pyplot to manage figure windows, but modify the GUI by accessing the underlying GTK widgets. We will create a figure with two plots and add a button to the toolbar and a label to the canvas. We will also add functionality to display the coordinates of the cursor when it moves over the plots.","steps":[{"title":"Import the required libraries","body":["We import the required libraries including matplotlib, gi, pyplot, and Gtk. We set the backend of matplotlib to use GTK4."],"code":[{"lang":"python","text":"import matplotlib\nmatplotlib.use('GTK4Agg')\nimport gi\nimport matplotlib.pyplot as plt\n\ngi.require_version('Gtk', '4.0')\nfrom gi.repository import Gtk"}]},{"title":"Create the figure and plots","body":["We create a figure with two subplots and plot two sets of data on them. We also add a legend to the plots."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.plot([1, 2, 3], 'ro-', label='easy as 1 2 3')\nax.plot([1, 4, 9], 'gs--', label='easy as 1 2 3 squared')\nax.legend()"}]},{"title":"Access the toolbar and vbox","body":["We access the toolbar and vbox attributes of the figure canvas manager."],"code":[{"lang":"python","text":"manager = fig.canvas.manager\ntoolbar = manager.toolbar\nvbox = manager.vbox"}]},{"title":"Add a button to the toolbar","body":["We create a button with a label and a tooltip, and connect it to a function that prints a message to the console. We add the button to the toolbar."],"code":[{"lang":"python","text":"button = Gtk.Button(label='Click me')\nbutton.connect('clicked', lambda button: print('hi mom'))\nbutton.set_tooltip_text('Click me for fun and profit')\ntoolbar.append(button)"}]},{"title":"Add a label to the canvas","body":["We create a label and set its text. We add the label to the vbox after the figure canvas."],"code":[{"lang":"python","text":"label = Gtk.Label()\nlabel.set_markup('Drag mouse over axes for position')\nvbox.insert_child_after(label, fig.canvas)"}]},{"title":"Update the label with cursor coordinates","body":["Update the label with cursor coordinates","We create a function that updates the label with the x and y coordinates of the cursor when it moves over the plots. We connect the function to the motion_notify_event of the canvas."],"code":[{"lang":"python","text":"def update(event):\n    if event.xdata is None:\n        label.set_markup('Drag mouse over axes for position')\n    else:\n        label.set_markup(\n            f'<span color=\"#ef0000\">x,y=({event.xdata}, {event.ydata})</span>')\n\nfig.canvas.mpl_connect('motion_notify_event', update)"}]},{"title":"Display the figure","body":["We display the figure with the added button and label."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-plotting-for-python-beginners":{"intro":"Matplotlib is a plotting library for the Python programming language and its numerical mathematics extension NumPy. It provides an object-oriented API for embedding plots into applications using general-purpose GUI toolkits like Tkinter, wxPython, Qt, or GTK. It also provides a procedural interface for non-interactive plotting.","steps":[{"title":"Import the Matplotlib Library","body":["To use Matplotlib in Python, you need to import it first. Type the following code to import the Matplotlib library:"],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt"}]},{"title":"Create a Simple Plot","body":["To create a simple plot in Matplotlib, you need to provide a list of numbers that you want to plot. In this case, we will plot a list of numbers against their index resulting in a straight line. Use a format string (here, 'o-r') to set the markers (circles), linestyle (solid line) and color (red)."],"code":[{"lang":"python","text":"plt.plot([1, 2, 3, 4], 'o-r')\nplt.ylabel('some numbers')\nplt.show()"}]},{"title":"Customize the Plot","body":["Matplotlib provides many options to customize the plot. You can change the color, linestyle, marker style, and many other options. Here is an example of how to change the color of the line to blue and the marker style to a plus sign:"],"code":[{"lang":"python","text":"plt.plot([1, 2, 3, 4], '+-b')\nplt.ylabel('some numbers')\nplt.show()"}]},{"title":"Add Labels and Titles","body":["Adding labels and titles to the plot is essential to make it more informative. The following code adds a title to the plot and labels to the x and y-axis:"],"code":[{"lang":"python","text":"plt.plot([1, 2, 3, 4], 'o-r')\nplt.title('Simple Plot')\nplt.xlabel('Index')\nplt.ylabel('Numbers')\nplt.show()"}]},{"title":"Save the Plot","body":["You can save the plot as an image file using the savefig method. The following code saves the plot as a PNG image:"],"code":[{"lang":"python","text":"plt.plot([1, 2, 3, 4], 'o-r')\nplt.title('Simple Plot')\nplt.xlabel('Index')\nplt.ylabel('Numbers')\nplt.savefig('simple_plot.png')"}]}],"commands":[],"reference":[{"path":"reference.py","text":"plt.plot([1, 2, 3, 4], 'o-r')\nplt.title('Simple Plot')\nplt.xlabel('Index')\nplt.ylabel('Numbers')\nplt.savefig('simple_plot.png')"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-creating-text-and-mathtext-using-pyplot":{"intro":"Matplotlib is a powerful data visualization library in Python. It provides a wide range of tools to create graphs and plots in Python. In this tutorial, we will learn how to create text and mathtext using pyplot.","steps":[{"title":"Import Required Libraries","body":["First, we need to import the required libraries. We will import numpy and matplotlib.pyplot libraries."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create Data","body":["Next, we will create data for the plot. We will create a sine wave using numpy library."],"code":[{"lang":"python","text":"t = np.arange(0.0, 2.0, 0.01)\ns = np.sin(2*np.pi*t)"}]},{"title":"Plot the Graph","body":["Now, we will plot the graph using plot() method of pyplot library."],"code":[{"lang":"python","text":"plt.plot(t, s)"}]},{"title":"Add Text to the Graph","body":["We can add text to the graph using text() method of pyplot library. We will add \"Hello, world!\" text at coordinates (0, -1)."],"code":[{"lang":"python","text":"plt.text(0, -1, r'Hello, world!', fontsize=15)"}]},{"title":"Add Title, X-label, and Y-label","body":["Add Title, X-label, and Y-label","We can add title, X-label, and Y-label to the graph using title(), xlabel(), and ylabel() methods of pyplot library. We will add \"Voltage vs Time\" as the title, \"Time [s]\" as X-label, and \"Voltage [mV]\" as Y-label."],"code":[{"lang":"python","text":"plt.title(r'Voltage vs Time', fontsize=20)\nplt.xlabel('Time [s]')\nplt.ylabel('Voltage [mV]')"}]},{"title":"Show the Graph","body":["Finally, we will show the graph using show() method of pyplot library."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-plotting-multiple-datasets":{"intro":"Matplotlib is a popular data visualization library in Python. In this lab, you will learn how to plot multiple datasets using a single call to the plot function in Matplotlib.","steps":[{"title":"Import the Required Libraries","body":[],"code":[{"lang":"python","text":"import numpy as np\nimport matplotlib.pyplot as plt\n%matplotlib inline"}]},{"title":"Create the Data","body":["In this step, we will create three different datasets using the arange function from NumPy. We will create a time series with 200ms intervals, ranging from 0 to 5 seconds."],"code":[{"lang":"python","text":"t = np.arange(0., 5., 0.2)"}]},{"title":"Plot the Data","body":["In this step, we will use the plot function in Matplotlib to plot all three datasets in a single call. We will use red dashes for the first dataset, blue squares for the second dataset, and green triangles for the third dataset."],"code":[{"lang":"python","text":"plt.plot(t, t, 'r--', label='linear')\nplt.plot(t, t**2, 'bs', label='quadratic')\nplt.plot(t, t**3, 'g^', label='cubic')\nplt.legend()\nplt.show()"}]},{"title":"Add Labels and Titles","body":["In this step, we will add a title to the plot and label the x and y axes."],"code":[{"lang":"python","text":"plt.plot(t, t, 'r--', label='linear')\nplt.plot(t, t**2, 'bs', label='quadratic')\nplt.plot(t, t**3, 'g^', label='cubic')\nplt.legend()\nplt.title(\"Multiple Datasets\")\nplt.xlabel(\"Time (s)\")\nplt.ylabel(\"Value\")\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"plt.plot(t, t, 'r--', label='linear')\nplt.plot(t, t**2, 'bs', label='quadratic')\nplt.plot(t, t**3, 'g^', label='cubic')\nplt.legend()\nplt.title(\"Multiple Datasets\")\nplt.xlabel(\"Time (s)\")\nplt.ylabel(\"Value\")\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-creating-matplotlib-subplots-in-python":{"intro":"Matplotlib is a Python library used for creating visualizations such as line plots, scatter plots, bar plots, and subplots, among others. In this lab, you will learn how to create a figure with two subplots using .pyplot.subplot.","steps":[{"title":"Import the necessary libraries","body":["Import the necessary libraries","For this tutorial, we will be using the pyplot module from the Matplotlib library and the numpy library."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Define the data","body":["We will define two sets of data that we will use to create our subplots."],"code":[{"lang":"python","text":"def f(t):\n    return np.exp(-t) * np.cos(2*np.pi*t)\n\nt1 = np.arange(0.0, 5.0, 0.1)\nt2 = np.arange(0.0, 5.0, 0.02)"}]},{"title":"Create the subplots","body":["We will create a figure with two subplots using .pyplot.subplot.","The subplot() function takes three arguments: the number of rows, the number of columns, and the index of the current plot. The index starts from 1 in the upper left corner and increases row-wise. In this example, we create a figure with two subplots: one on top and one on the bottom.","In the first subplot, we plot t1 against f(t1) and t2 against f(t2). We set the color of the first plot to blue and add circular markers to each data point. We set the color of the second plot to black.","In the second subplot, we plot t2 against the cosine function of 2*np.pi*t2. We set the color of the plot to orange and the linestyle to dashed."],"code":[{"lang":"python","text":"plt.figure()\n\nplt.subplot(211)\nplt.plot(t1, f(t1), color='tab:blue', marker='o')\nplt.plot(t2, f(t2), color='black')\n\nplt.subplot(212)\nplt.plot(t2, np.cos(2*np.pi*t2), color='tab:orange', linestyle='--')\n\nplt.show()"}]},{"title":"References","body":["The use of the following functions, methods, classes, and modules is shown in this example:","• matplotlib.pyplot.figure • matplotlib.pyplot.subplot"],"code":[]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-creating-a-bezier-curve":{"intro":"In this tutorial, we will learn how to create a Bezier Curve using Python's Matplotlib library. A Bezier Curve is a mathematical curve that is commonly used in computer graphics to create smooth and aesthetically pleasing shapes. We will create a simple example of a Bezier Curve using Matplotlib's PathPatch object.","steps":[{"title":"Importing Libraries","body":["To create a Bezier Curve using Matplotlib, we need to import the necessary libraries. We will import matplotlib.pyplot for creating the plot and matplotlib.patches for creating the PathPatch object."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport matplotlib.patches as mpatches\nimport matplotlib.path as mpath"}]},{"title":"Creating the Path","body":["Next, we will create the Path object for the Bezier Curve. The Path object takes in a list of vertices and codes that specify the type of path between the vertices. In this case, we will use a MOVETO code to move to the starting point, followed by two CURVE3 codes to specify the control points and ending point, and finally a CLOSEPOLY code to close the path."],"code":[{"lang":"python","text":"Path = mpath.Path\n\nbezier_path = Path([(0, 0), (1, 0), (1, 1), (0, 0)],\n                   [Path.MOVETO, Path.CURVE3, Path.CURVE3, Path.CLOSEPOLY])"}]},{"title":"Creating the PathPatch Object","body":["Now that we have the Path object, we can create the PathPatch object that will be used to draw the Bezier Curve on the plot. We will set the facecolor to 'none' so that only the curve is drawn and not filled."],"code":[{"lang":"python","text":"bezier_patch = mpatches.PathPatch(bezier_path, fc=\"none\")"}]},{"title":"Creating the Plot","body":["We can now create the plot by adding the PathPatch object to the axes and plotting a red point that should lie on the curve. We will also set the title of the plot to 'Bezier Curve'.","The final code should look like this:"],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\n\nax.add_patch(bezier_patch)\nax.plot([0.75], [0.25], \"ro\")\nax.set_title('Bezier Curve')\n\nplt.show()"},{"lang":"python","text":"import matplotlib.pyplot as plt\nimport matplotlib.patches as mpatches\nimport matplotlib.path as mpath\n\nPath = mpath.Path\n\nbezier_path = Path([(0, 0), (1, 0), (1, 1), (0, 0)],\n                   [Path.MOVETO, Path.CURVE3, Path.CURVE3, Path.CLOSEPOLY])\n\nbezier_patch = mpatches.PathPatch(bezier_path, fc=\"none\")\n\nfig, ax = plt.subplots()\n\nax.add_patch(bezier_patch)\nax.plot([0.75], [0.25], \"ro\")\nax.set_title('Bezier Curve')\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"import matplotlib.pyplot as plt\nimport matplotlib.patches as mpatches\nimport matplotlib.path as mpath\n\nPath = mpath.Path\n\nbezier_path = Path([(0, 0), (1, 0), (1, 1), (0, 0)],\n                   [Path.MOVETO, Path.CURVE3, Path.CURVE3, Path.CLOSEPOLY])\n\nbezier_patch = mpatches.PathPatch(bezier_path, fc=\"none\")\n\nfig, ax = plt.subplots()\n\nax.add_patch(bezier_patch)\nax.plot([0.75], [0.25], \"ro\")\nax.set_title('Bezier Curve')\n\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-quadmesh-plotting-tutorial":{"intro":"This tutorial will guide you through the usage of the Matplotlib library to create a QuadMesh plot. QuadMesh is a faster generalization of the pcolor function, but with some restrictions. The demo in this tutorial will illustrate a bug in QuadMesh with masked data.","steps":[{"title":"Importing the necessary libraries","body":["Importing the necessary libraries"],"code":[{"lang":"python","text":"import numpy as np\nfrom matplotlib import pyplot as plt"}]},{"title":"Defining the data","body":[],"code":[{"lang":"python","text":"n = 12\nx = np.linspace(-1.5, 1.5, n)\ny = np.linspace(-1.5, 1.5, n * 2)\nX, Y = np.meshgrid(x, y)\nQx = np.cos(Y) - np.cos(X)\nQz = np.sin(Y) + np.sin(X)\nZ = np.sqrt(X**2 + Y**2) / 5\nZ = (Z - Z.min()) / (Z.max() - Z.min())\nZm = np.ma.masked_where(np.abs(Qz) < 0.5 * np.max(Qz), Z)"}]},{"title":"Creating the plot","body":[],"code":[{"lang":"python","text":"fig, axs = plt.subplots(nrows=1, ncols=3)\naxs[0].pcolormesh(Qx, Qz, Z, shading='gouraud')\naxs[0].set_title('Without masked values')\ncmap = plt.colormaps[plt.rcParams['image.cmap']].with_extremes(bad='y')\naxs[1].pcolormesh(Qx, Qz, Zm, shading='gouraud', cmap=cmap)\naxs[1].set_title('With masked values')\naxs[2].pcolormesh(Qx, Qz, Zm, shading='gouraud')\naxs[2].set_title('With masked values')\nfig.tight_layout()\nplt.show()"}]},{"title":"Explanation","body":["• Step 2: The data is defined using numpy arrays. The X and Y arrays are used to create a meshgrid, which is used to calculate the Qx and Qz values. The Z values are then calculated based on the Qx and Qz values. The Zm array is created by masking values where the absolute value of Qz is less than 0.5 times the maximum value of Qz. • Step 3: A figure with three subplots is created using the subplots method. The pcolormesh function is used to create a QuadMesh plot for each subplot. The first subplot shows the plot without masked values. The second subplot shows the plot with masked values and a custom colormap where the masked…"],"code":[]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-advanced-quiver-and-quiverkey-functions":{"intro":"Matplotlib is a data visualization library in Python that allows users to create a wide range of 2D and 3D plots. One of the many useful features of Matplotlib is the ability to create quiver plots, which display vector fields.","steps":[{"title":"Arrows Scale with Plot Width, Not View","body":["Arrows Scale with Plot Width, Not View","The quiver() function can be used to create a quiver plot. By default, the arrows in the plot will scale with the data, rather than the plot itself. This can make it difficult to see arrows that are close to the edge of the plot."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nX, Y = np.meshgrid(np.arange(0, 2 * np.pi, .2), np.arange(0, 2 * np.pi, .2))\nU = np.cos(X)\nV = np.sin(Y)\n\nfig1, ax1 = plt.subplots()\nax1.set_title('Arrows scale with plot width, not view')\nQ = ax1.quiver(X, Y, U, V, units='width')\nqk = ax1.quiverkey(Q, 0.9, 0.9, 2, r'$2 \\frac{m}{s}$', labelpos='E',\n                   coordinates='figure')\nplt.show()"}]},{"title":"Pivot Point and Arrow Frequency","body":["Pivot Point and Arrow Frequency","The quiver() function can also be used to customize the pivot point of the arrows and the frequency at which they are displayed. The pivot parameter can be set to 'mid' or 'tip', and the arrays passed to quiver() can be sliced to display only every nth arrow."],"code":[{"lang":"python","text":"fig2, ax2 = plt.subplots()\nax2.set_title(\"pivot='mid'; every third arrow; units='inches'\")\nQ = ax2.quiver(X[::3, ::3], Y[::3, ::3], U[::3, ::3], V[::3, ::3],\n               pivot='mid', units='inches')\nqk = ax2.quiverkey(Q, 0.9, 0.9, 1, r'$1 \\frac{m}{s}$', labelpos='E',\n                   coordinates='figure')\nax2.scatter(X[::3, ::3], Y[::3, ::3], color='r', s=5)\nplt.show()"}]},{"title":"Scale Arrows with X View","body":["The quiver() function also allows for scaling arrows with the x view. This can be useful for displaying arrows at different scales depending on the data."],"code":[{"lang":"python","text":"fig3, ax3 = plt.subplots()\nax3.set_title(\"pivot='tip'; scales with x view\")\nM = np.hypot(U, V)\nQ = ax3.quiver(X, Y, U, V, M, units='x', pivot='tip', width=0.022,\n               scale=1 / 0.15)\nqk = ax3.quiverkey(Q, 0.9, 0.9, 1, r'$1 \\frac{m}{s}$', labelpos='E',\n                   coordinates='figure')\nax3.scatter(X, Y, color='0.5', s=1)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig3, ax3 = plt.subplots()\nax3.set_title(\"pivot='tip'; scales with x view\")\nM = np.hypot(U, V)\nQ = ax3.quiver(X, Y, U, V, M, units='x', pivot='tip', width=0.022,\n               scale=1 / 0.15)\nqk = ax3.quiverkey(Q, 0.9, 0.9, 1, r'$1 \\frac{m}{s}$', labelpos='E',\n                   coordinates='figure')\nax3.scatter(X, Y, color='0.5', s=1)\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-quiver-plot":{"intro":"This lab will guide you through how to create a quiver plot using Matplotlib in Python. A quiver plot displays vector fields as arrows. It is useful in visualizing fluid flows, electric and magnetic fields, and other types of vector fields.","steps":[{"title":"Import Libraries","body":["We need to import the numpy and matplotlib libraries to create a quiver plot."],"code":[{"lang":"python","text":"import numpy as np\nimport matplotlib.pyplot as plt"}]},{"title":"Create Data","body":["We need to create the X and Y coordinates using the np.meshgrid() function. Then, we create the U and V arrays that represent the vector fields."],"code":[{"lang":"python","text":"X = np.arange(-10, 10, 1)\nY = np.arange(-10, 10, 1)\nU, V = np.meshgrid(X, Y)"}]},{"title":"Create the Quiver Plot","body":["We can create the quiver plot using the ax.quiver() function. We pass in the X, Y, U, and V arrays as parameters."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nq = ax.quiver(X, Y, U, V)"}]},{"title":"Create the Quiver Key","body":["We can add a quiver key to the plot to show the scale of the arrows. We use the ax.quiverkey() function to add the key. We pass in the q object, the X and Y position of the key, the length of the arrow, the label for the key, and the position of the label."],"code":[{"lang":"python","text":"ax.quiverkey(q, X=0.3, Y=1.1, U=10,\n             label='Quiver key, length = 10', labelpos='E')"}]},{"title":"Display the Plot","body":["We can display the plot using the plt.show() function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-3d-quiver-plot":{"intro":"In this lab, you will learn how to create a 3D quiver plot using Python Matplotlib. A quiver plot displays a vector field as arrows. The arrows point in the direction of the vectors and their length represents the magnitude of the vectors.","steps":[{"title":"Import Libraries and Set Up Plot","body":["Import Libraries and Set Up Plot","The first step is to import the necessary libraries and set up the plot. In this example, we will be using Matplotlib's pyplot module and its 3d toolkit for creating the 3D plot."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nax = plt.figure().add_subplot(projection='3d')"}]},{"title":"Create the Grid","body":["Next, we will create a grid of points on which we will display the vector field. In this example, we will create a meshgrid of points using NumPy's meshgrid function. The arange function is used to create an array of evenly spaced points within a specified interval."],"code":[{"lang":"python","text":"x, y, z = np.meshgrid(np.arange(-0.8, 1, 0.2),\n                      np.arange(-0.8, 1, 0.2),\n                      np.arange(-0.8, 1, 0.8))"}]},{"title":"Define the Direction of the Arrows","body":["Define the Direction of the Arrows","Now we will define the direction of the arrows. In this example, we will define the direction of the arrows using NumPy's trigonometric functions. The sin and cos functions are used to create the u, v, and w arrays that represent the direction of the arrows in the x, y, and z directions."],"code":[{"lang":"python","text":"u = np.sin(np.pi * x) * np.cos(np.pi * y) * np.cos(np.pi * z)\nv = -np.cos(np.pi * x) * np.sin(np.pi * y) * np.cos(np.pi * z)\nw = (np.sqrt(2.0 / 3.0) * np.cos(np.pi * x) * np.cos(np.pi * y) *\n     np.sin(np.pi * z))"}]},{"title":"Create the Quiver Plot","body":["With the grid and direction of the arrows defined, we can create the quiver plot. In this example, we will use Matplotlib's quiver function to create the plot. The length parameter sets the length of the arrows and the normalize parameter normalizes the arrows to a length of 1."],"code":[{"lang":"python","text":"ax.quiver(x, y, z, u, v, w, length=0.1, normalize=True)"}]},{"title":"Display the Plot","body":["Finally, we will display the plot using Matplotlib's show function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-create-radar-charts-with-python-matplotlib":{"intro":"In this lab, you will learn how to create a radar chart using Python's Matplotlib library. A radar chart, also known as a spider or star chart, is a graphical method of displaying multivariate data in the form of a two-dimensional chart of three or more quantitative variables represented on axes starting from the same point. It is often used to compare different products or solutions based on several factors.","steps":[{"title":"Import Libraries","body":["First, we need to import the necessary libraries. Matplotlib and numpy are required for this tutorial."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Define the Radar Chart Function","body":["Define the Radar Chart Function","Next, we will define a function to create a radar chart. This function will take two arguments: num_vars and frame. num_vars is the number of variables for the radar chart, and frame specifies the shape of the frame surrounding the axes."],"code":[{"lang":"python","text":"from matplotlib.patches import Circle, RegularPolygon\nfrom matplotlib.path import Path\nfrom matplotlib.projections import register_projection\nfrom matplotlib.projections.polar import PolarAxes\nfrom matplotlib.spines import Spine\nfrom matplotlib.transforms import Affine2D\n\ndef radar_factory(num_vars, frame='circle'):\n    # code for the function goes here"}]},{"title":"Define the Radar Transform and Radar Axes Classes","body":["Define the Radar Transform and Radar Axes Classes","Within the radar_factory function, we will define the RadarTransform and RadarAxes classes. These classes will be used to create the radar chart."],"code":[{"lang":"python","text":"class RadarTransform(PolarAxes.PolarTransform):\n    # code for the RadarTransform class goes here\n\nclass RadarAxes(PolarAxes):\n    # code for the RadarAxes class goes here"}]},{"title":"Define the fill and plot Methods","body":["Define the fill and plot Methods","Within the RadarAxes class, we will define the fill and plot methods. These methods will be used to fill the area inside the chart and plot the data points, respectively."],"code":[{"lang":"python","text":"class RadarAxes(PolarAxes):\n    # code for the RadarAxes class goes here\n\n    def fill(self, *args, closed=True, **kwargs):\n        # override the fill method\n        return super().fill(closed=closed, *args, **kwargs)\n\n    def plot(self, *args, **kwargs):\n        # override the plot method\n        lines = super().plot(*args, **kwargs)\n        for line in lines:\n            self._close_line(line)\n\n    def _close_line(self, line):\n        # helper method to close the line\n        x, y = line.get_data()\n        if x[0] != x[-1]:\n            x = np.append(x, x[0])\n            y = np.append(y, y[0])\n            line.set_data(x, y)"}]},{"title":"Define the set_varlabels, _gen_axes_patch, and _gen_axes_spines Methods","body":["Define the set_varlabels, _gen_axes_patch, and _gen_axes_spines Methods","Within the RadarAxes class, we will also define the set_varlabels, _gen_axes_patch, and _gen_axes_spines methods. These methods will set the variable labels, generate the axes patch, and generate the axes spines, respectively."],"code":[{"lang":"python","text":"class RadarAxes(PolarAxes):\n    # code for the RadarAxes class goes here\n\n    def set_varlabels(self, labels):\n        self.set_thetagrids(np.degrees(theta), labels)\n\n    def _gen_axes_patch(self):\n        if frame == 'circle':\n            return Circle((0.5, 0.5), 0.5)\n        elif frame == 'polygon':\n            return RegularPolygon((0.5, 0.5), num_vars,\n                                  radius=.5, edgecolor=\"k\")\n        else:\n            raise ValueError(\"Unknown value for 'frame': %s\" % frame)\n\n    def _gen_axes_spines(self):\n        if frame == 'circle':\n            return super()._gen_axes_spines()\n        elif frame == 'polygon':\n            spine = Spine(axes=self,\n                          spine_type='circle',\n                          path=Path.unit_regular_polygon(num_vars))\n            spine.set_transform(Affine2D().scale(.5).translate(.5, .5)\n                                + self.transAxes)\n            return {'polar': spine}\n        else:\n            raise ValueError(\"Unknown value for 'frame': %s\" % frame)"}]},{"title":"Define the Example Data","body":["Now, we will define the example data that we will use to create the radar chart. This data is taken from a study on pollution source profile estimates."],"code":[{"lang":"python","text":"def example_data():\n    data = [\n        ['Sulfate', 'Nitrate', 'EC', 'OC1', 'OC2', 'OC3', 'OP', 'CO', 'O3'],\n        ('Basecase', [\n            [0.88, 0.01, 0.03, 0.03, 0.00, 0.06, 0.01, 0.00, 0.00],\n            [0.07, 0.95, 0.04, 0.05, 0.00, 0.02, 0.01, 0.00, 0.00],\n            [0.01, 0.02, 0.85, 0.19, 0.05, 0.10, 0.00, 0.00, 0.00],\n            [0.02, 0.01, 0.07, 0.01, 0.21, 0.12, 0.98, 0.00, 0.00],\n            [0.01, 0.01, 0.02, 0.71, 0.74, 0.70, 0.00, 0.00, 0.00]]),\n        ('With CO', [\n            [0.88, 0.02, 0.02, 0.02, 0.00, 0.05, 0.00, 0.05, 0.00],\n            [0.08, 0.94, 0.04, 0.02, 0.00, 0.01, 0.12, 0.04, 0.00],\n            [0.01, 0.01, 0.79, 0.10, 0.00, 0.05, 0.00, 0.31, 0.00],\n            [0.00, 0.02, 0.03, 0.38, 0.31, 0.31, 0.00, 0.59, 0.00],\n            [0.02, 0.02, 0.11, 0.47, 0.69, 0.58, 0.88, 0.00, 0.00]]),\n        ('With O3', [\n            [0.89, 0.01, 0.07, 0.00, 0.00, 0.05, 0.00, 0.00, 0.03],\n            [0.07, 0.95, 0.05, 0.04, 0.00, 0.02, 0.12, 0.00, 0.00],\n            [0.01, 0.02, 0.86, 0.27, 0.16, 0.19, 0.00, 0.00, 0.00],\n            [0.01, 0.03, 0.00, 0.32, 0.29, 0.27, 0.00, 0.00, 0.95],\n            [0.02, 0.00, 0.03, 0.37, 0.56, 0.47, 0.87, 0.00, 0.00]]),\n        ('CO & O3', [\n            [0.87, 0.01, 0.08, 0.00, 0.00, 0.04, 0.00, 0.00, 0.01],\n            [0.09, 0.95, 0.02, 0.03, 0.00, 0.01, 0.13, 0.06, 0.00],\n            [0.01, 0.02, 0.71, 0.24, 0.13, 0.16, 0.00, 0.50, 0.00],\n            [0.01, 0.03, 0.00, 0.28, 0.24, 0.23, 0.00, 0.44, 0.88],\n            [0.02, 0.00, 0.18, 0.45, 0.64, 0.55, 0.86, 0.00, 0.16]])\n    ]\n    return data"}]},{"title":"Set the Number of Variables and Calculate the Axis Angles","body":["Set the Number of Variables and Calculate the Axis Angles","We will now set the number of variables and calculate the evenly-spaced axis angles using numpy."],"code":[{"lang":"python","text":"N = 9\ntheta = radar_factory(N, frame='polygon')"}]},{"title":"Create the Radar Chart","body":["Finally, we can create the radar chart using the example data and the RadarAxes class."],"code":[{"lang":"python","text":"data = example_data()\nspoke_labels = data.pop(0)\n\nfig, axs = plt.subplots(figsize=(9, 9), nrows=2, ncols=2,\n                        subplot_kw=dict(projection='radar'))\nfig.subplots_adjust(wspace=0.25, hspace=0.20, top=0.85, bottom=0.05)\n\ncolors = ['b', 'r', 'g', 'm', 'y']\nfor ax, (title, case_data) in zip(axs.flat, data):\n    ax.set_rgrids([0.2, 0.4, 0.6, 0.8])\n    ax.set_title(title, weight='bold', size='medium', position=(0.5, 1.1),\n                 horizontalalignment='center', verticalalignment='center')\n    for d, color in zip(case_data, colors):\n        ax.plot(theta, d, color=color)\n        ax.fill(theta, d, facecolor=color, alpha=0.25, label='_nolegend_')\n    ax.set_varlabels(spoke_labels)\n\nlabels = ('Factor 1', 'Factor 2', 'Factor 3', 'Factor 4', 'Factor 5')\nlegend = axs[0, 0].legend(labels, loc=(0.9, .95),\n                          labelspacing=0.1, fontsize='small')\n\nfig.text(0.5, 0.965, '5-Factor Solution Profiles Across Four Scenarios',\n         horizontalalignment='center', color='black', weight='bold',\n         size='large')\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"data = example_data()\nspoke_labels = data.pop(0)\n\nfig, axs = plt.subplots(figsize=(9, 9), nrows=2, ncols=2,\n                        subplot_kw=dict(projection='radar'))\nfig.subplots_adjust(wspace=0.25, hspace=0.20, top=0.85, bottom=0.05)\n\ncolors = ['b', 'r', 'g', 'm', 'y']\nfor ax, (title, case_data) in zip(axs.flat, data):\n    ax.set_rgrids([0.2, 0.4, 0.6, 0.8])\n    ax.set_title(title, weight='bold', size='medium', position=(0.5, 1.1),\n                 horizontalalignment='center', verticalalignment='center')\n    for d, color in zip(case_data, colors):\n        ax.plot(theta, d, color=color)\n        ax.fill(theta, d, facecolor=color, alpha=0.25, label='_nolegend_')\n    ax.set_varlabels(spoke_labels)\n\nlabels = ('Factor 1', 'Factor 2', 'Factor 3', 'Factor 4', 'Factor 5')\nlegend = axs[0, 0].legend(labels, loc=(0.9, .95),\n                          labelspacing=0.1, fontsize='small')\n\nfig.text(0.5, 0.965, '5-Factor Solution Profiles Across Four Scenarios',\n         horizontalalignment='center', color='black', weight='bold',\n         size='large')\n\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-create-radian-plots-with-matplotlib":{"intro":"This tutorial will show you how to create a plot with radians using the Python Matplotlib package. You will learn how to use the unit class to determine the tick locating, formatting, and axis labeling.","steps":[{"title":"Import necessary packages","body":["First, import the necessary packages, including matplotlib.pyplot and numpy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create data","body":["Create an array of values between 0 and 15 in increments of 0.01, and convert them to radians using the radians function from the basic_units package."],"code":[{"lang":"python","text":"from basic_units import radians\nx = [val*radians for val in np.arange(0, 15, 0.01)]"}]},{"title":"Create a figure","body":["Create a figure with two subplots using the subplots function from matplotlib.pyplot."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(2)"}]},{"title":"Plot data in the first subplot","body":["Plot data in the first subplot","Plot the cosine of the x values in the first subplot using the plot function from matplotlib.pyplot. Use the xunits parameter to specify that the x-axis should be in radians."],"code":[{"lang":"python","text":"from basic_units import cos\naxs[0].plot(x, cos(x), xunits=radians)"}]},{"title":"Plot data in the second subplot","body":["Plot data in the second subplot","Plot the cosine of the x values in the second subplot using the plot function from matplotlib.pyplot. Use the xunits parameter to specify that the x-axis should be in degrees."],"code":[{"lang":"python","text":"from basic_units import degrees\naxs[1].plot(x, cos(x), xunits=degrees)"}]},{"title":"Add labels and adjust layout","body":["Add a title and axis labels to the subplots using the title, xlabel, and ylabel functions from matplotlib.pyplot. Adjust the layout of the subplots using the tight_layout function."],"code":[{"lang":"python","text":"axs[0].set_title('Cosine with Radian X-Axis')\naxs[0].set_xlabel('Radians')\naxs[0].set_ylabel('Cosine')\naxs[1].set_title('Cosine with Degree X-Axis')\naxs[1].set_xlabel('Degrees')\naxs[1].set_ylabel('Cosine')\nfig.tight_layout()"}]},{"title":"Display the plot","body":["Display the plot using the show function from matplotlib.pyplot."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-radio-button-sine-wave-visualizat":{"intro":"Radio buttons are a type of input element that allows users to select one option from a group of predefined options. In this lab, we will use the matplotlib library to create a visualization with radio buttons that let the user choose between different sine waves to be shown in the plot.","steps":[{"title":"Import Required Libraries","body":["We will start by importing the required libraries for this lab - numpy and matplotlib."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nfrom matplotlib.widgets import RadioButtons"}]},{"title":"Create Data","body":["Next, we will create the data that will be used in the plot. We will create three different sine waves with different frequencies using the numpy library."],"code":[{"lang":"python","text":"t = np.arange(0.0, 2.0, 0.01)\ns0 = np.sin(2*np.pi*t)\ns1 = np.sin(4*np.pi*t)\ns2 = np.sin(8*np.pi*t)"}]},{"title":"Create the Plot and Radio Buttons","body":["Create the Plot and Radio Buttons","Now, we will create the plot and radio buttons. We will use the subplots() function to create the plot and the RadioButtons() function to create the radio buttons."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nl, = ax.plot(t, s0, lw=2, color='red')\nfig.subplots_adjust(left=0.3)\n\naxcolor = 'lightgoldenrodyellow'\nrax = fig.add_axes([0.05, 0.7, 0.15, 0.15], facecolor=axcolor)\nradio = RadioButtons(rax, ('1 Hz', '2 Hz', '4 Hz'),\n                     label_props={'color': 'cmy', 'fontsize': [12, 14, 16]},\n                     radio_props={'s': [16, 32, 64]})"}]},{"title":"Add Functionality to the Radio Buttons","body":["Add Functionality to the Radio Buttons"],"code":[{"lang":"python","text":"def hzfunc(label):\n    hzdict = {'1 Hz': s0, '2 Hz': s1, '4 Hz': s2}\n    ydata = hzdict[label]\n    l.set_ydata(ydata)\n    fig.canvas.draw()\nradio.on_clicked(hzfunc)\n\nrax = fig.add_axes([0.05, 0.4, 0.15, 0.15], facecolor=axcolor)\nradio2 = RadioButtons(\n    rax, ('red', 'blue', 'green'),\n    label_props={'color': ['red', 'blue', 'green']},\n    radio_props={\n        'facecolor': ['red', 'blue', 'green'],\n        'edgecolor': ['darkred', 'darkblue', 'darkgreen'],\n    })\n\n\ndef colorfunc(label):\n    l.set_color(label)\n    fig.canvas.draw()\nradio2.on_clicked(colorfunc)\n\nrax = fig.add_axes([0.05, 0.1, 0.15, 0.15], facecolor=axcolor)\nradio3 = RadioButtons(rax, ('-', '--', '-.', ':'))\n\n\ndef stylefunc(label):\n    l.set_linestyle(label)\n    fig.canvas.draw()\nradio3.on_clicked(stylefunc)"}]},{"title":"Display the Plot","body":["Finally, we will display the plot using the show() function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-text-object-concatenation":{"intro":"In this lab, you will learn how to concatenate text objects with different properties using Matplotlib. Concatenation is the process of combining multiple text objects into a single string. This can be useful when creating annotations or labels for visualizations.","steps":[{"title":"Create the First Text Object","body":["The first step is to create the first text object using ~.Axes.text. This text object will be the starting point for the concatenation process. The following code creates a red text object with the word \"Matplotlib\" at position (0.1, 0.5) on the plot."],"code":[{"lang":"python","text":"text = ax.text(.1, .5, \"Matplotlib\", color=\"red\")"}]},{"title":"Create the Subsequent Text Objects","body":["Create the Subsequent Text Objects","The next step is to create the subsequent text objects using ~.Axes.annotate. This function allows you to position the text object relative to the previous text object. The following code creates three text objects that are positioned to the right of the previous text object."],"code":[{"lang":"python","text":"text = ax.annotate(\n    \" says,\", xycoords=text, xy=(1, 0), verticalalignment=\"bottom\",\n    color=\"gold\", weight=\"bold\")  # custom properties\ntext = ax.annotate(\n    \" hello\", xycoords=text, xy=(1, 0), verticalalignment=\"bottom\",\n    color=\"green\", style=\"italic\")  # custom properties\ntext = ax.annotate(\n    \" world!\", xycoords=text, xy=(1, 0), verticalalignment=\"bottom\",\n    color=\"blue\", family=\"serif\")  # custom properties"}]},{"title":"Customize the Text Objects","body":["You can customize the appearance of the text objects using various properties. In the previous code block, we set the color, weight, style, and family properties for each text object. You can experiment with different properties to achieve the desired appearance."],"code":[]},{"title":"Display the Plot","body":["Once you have created and customized all the text objects, you can display the plot using plt.show(). The following code block shows the complete code for the plot."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\nplt.rcParams[\"font.size\"] = 20\nax = plt.figure().add_subplot(xticks=[], yticks=[])\n\n# The first word, created with text().\ntext = ax.text(.1, .5, \"Matplotlib\", color=\"red\")\n# Subsequent words, positioned with annotate(), relative to the preceding one.\ntext = ax.annotate(\n    \" says,\", xycoords=text, xy=(1, 0), verticalalignment=\"bottom\",\n    color=\"gold\", weight=\"bold\")  # custom properties\ntext = ax.annotate(\n    \" hello\", xycoords=text, xy=(1, 0), verticalalignment=\"bottom\",\n    color=\"green\", style=\"italic\")  # custom properties\ntext = ax.annotate(\n    \" world!\", xycoords=text, xy=(1, 0), verticalalignment=\"bottom\",\n    color=\"blue\", family=\"serif\")  # custom properties\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"import matplotlib.pyplot as plt\n\nplt.rcParams[\"font.size\"] = 20\nax = plt.figure().add_subplot(xticks=[], yticks=[])\n\n# The first word, created with text().\ntext = ax.text(.1, .5, \"Matplotlib\", color=\"red\")\n# Subsequent words, positioned with annotate(), relative to the preceding one.\ntext = ax.annotate(\n    \" says,\", xycoords=text, xy=(1, 0), verticalalignment=\"bottom\",\n    color=\"gold\", weight=\"bold\")  # custom properties\ntext = ax.annotate(\n    \" hello\", xycoords=text, xy=(1, 0), verticalalignment=\"bottom\",\n    color=\"green\", style=\"italic\")  # custom properties\ntext = ax.annotate(\n    \" world!\", xycoords=text, xy=(1, 0), verticalalignment=\"bottom\",\n    color=\"blue\", family=\"serif\")  # custom properties\n\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-animated-3d-random-walk-in-matplotlib":{"intro":"In this lab, we will learn how to create an animated 3D random walk plot using Matplotlib library in Python. We will create a 3D plot and simulate a random walk with 40 particles that move randomly in 3D space.","steps":[{"title":"Import Required Libraries","body":["We begin by importing the required libraries. We will use numpy to generate random numbers and matplotlib to create the plot."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nimport matplotlib.animation as animation"}]},{"title":"Define Random Walk Function","body":["We define a function that generates a random walk with a given number of steps and maximum step size. The function takes two inputs: num_steps is the total number of steps in the random walk and max_step is the maximum size of each step. We use numpy.random to generate random numbers for the steps and numpy.cumsum to compute the cumulative sum of the steps to obtain the final position."],"code":[{"lang":"python","text":"def random_walk(num_steps, max_step=0.05):\n    \"\"\"Return a 3D random walk as (num_steps, 3) array.\"\"\"\n    start_pos = np.random.random(3)\n    steps = np.random.uniform(-max_step, max_step, size=(num_steps, 3))\n    walk = start_pos + np.cumsum(steps, axis=0)\n    return walk"}]},{"title":"Define Update Function","body":["We define a function that updates the plot for each frame of the animation. The function takes three inputs: num is the current frame number, walks is a list of all the random walks, and lines is a list of all the lines in the plot. For each line and walk, we update the data for the x, y, and z coordinates of the line up to the current frame number. We use line.set_data() and line.set_3d_properties() to update the x-y and z coordinates, respectively."],"code":[{"lang":"python","text":"def update_lines(num, walks, lines):\n    for line, walk in zip(lines, walks):\n        # NOTE: there is no .set_data() for 3 dim data...\n        line.set_data(walk[:num, :2].T)\n        line.set_3d_properties(walk[:num, 2])\n    return lines"}]},{"title":"Generate Random Walks","body":["We generate 40 random walks with 30 steps each using the random_walk() function defined earlier. We store all the random walks in a list called walks."],"code":[{"lang":"python","text":"# Data: 40 random walks as (num_steps, 3) arrays\nnum_steps = 30\nwalks = [random_walk(num_steps) for index in range(40)]"}]},{"title":"Create 3D Plot","body":["We create a 3D plot using matplotlib. We add an empty line for each random walk to the plot. We set the limits for the x, y, and z axes to be between 0 and 1."],"code":[{"lang":"python","text":"# Attaching 3D axis to the figure\nfig = plt.figure()\nax = fig.add_subplot(projection=\"3d\")\n\n# Create lines initially without data\nlines = [ax.plot([], [], [])[0] for _ in walks]\n\n# Setting the axes properties\nax.set(xlim3d=(0, 1), xlabel='X')\nax.set(ylim3d=(0, 1), ylabel='Y')\nax.set(zlim3d=(0, 1), zlabel='Z')"}]},{"title":"Create Animation","body":["We create an animation using the FuncAnimation class from matplotlib.animation. We pass the figure object, the update function, the total number of frames (which is equal to the number of steps in the random walks), the list of all random walks, and the list of all lines as arguments to the FuncAnimation constructor."],"code":[{"lang":"python","text":"# Creating the Animation object\nani = animation.FuncAnimation(\n    fig, update_lines, num_steps, fargs=(walks, lines), interval=100)"}]},{"title":"Display Animation","body":["Finally, we display the animation using plt.show()."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-thresholding-an-image-with-rangeslider":{"intro":"This lab will demonstrate how to use the RangeSlider widget in Matplotlib to control the thresholding of an image. The purpose of thresholding is to convert a grayscale image into a binary image, where the pixels are either black or white. This is useful for image segmentation, where we want to extract certain features from the image.","steps":[{"title":"Generate a fake image","body":["First, we will generate a fake grayscale image using NumPy's random module. We will set the seed to ensure that the results are reproducible."],"code":[{"lang":"python","text":"np.random.seed(19680801)\nN = 128\nimg = np.random.randn(N, N)"}]},{"title":"Display the image and its histogram","body":["Display the image and its histogram","Next, we will display the image using Matplotlib's imshow function, and its histogram using hist. We will create a figure with two subplots, one for the image and one for the histogram."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(1, 2, figsize=(10, 5))\nfig.subplots_adjust(bottom=0.25)\n\nim = axs[0].imshow(img)\naxs[1].hist(img.flatten(), bins='auto')\naxs[1].set_title('Histogram of pixel intensities')"}]},{"title":"Create the RangeSlider","body":["We will now create the RangeSlider widget, which will allow us to adjust the threshold of the image. We will create a new axis for the slider and add it to the figure."],"code":[{"lang":"python","text":"slider_ax = fig.add_axes([0.20, 0.1, 0.60, 0.03])\nslider = RangeSlider(slider_ax, \"Threshold\", img.min(), img.max())"}]},{"title":"Add vertical lines to the histogram","body":["Add vertical lines to the histogram","To make it easier to see the effect of the thresholding, we will add vertical lines to the histogram to indicate the current threshold values. We will create two lines for the lower and upper threshold values, respectively."],"code":[{"lang":"python","text":"lower_limit_line = axs[1].axvline(slider.val[0], color='k')\nupper_limit_line = axs[1].axvline(slider.val[1], color='k')"}]},{"title":"Create a callback function for the slider","body":["Create a callback function for the slider","We will create a callback function that will be called whenever the user changes the threshold values using the slider. The function will update the image's colormap and the positions of the vertical lines on the histogram."],"code":[{"lang":"python","text":"def update(val):\n    # The val passed to a callback by the RangeSlider will\n    # be a tuple of (min, max)\n\n    # Update the image's colormap\n    im.norm.vmin = val[0]\n    im.norm.vmax = val[1]\n\n    # Update the position of the vertical lines\n    lower_limit_line.set_xdata([val[0], val[0]])\n    upper_limit_line.set_xdata([val[1], val[1]])\n\n    # Redraw the figure to ensure it updates\n    fig.canvas.draw_idle()\n\n\nslider.on_changed(update)"}]},{"title":"Display the figure","body":["Finally, we will display the figure with the image and the slider."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-vector-graphics-rasterization-with-python":{"intro":"In this lab, you will learn about rasterization for vector graphics. Rasterization is a process of converting vector graphics into a raster image (pixels). It can speed up rendering and produce smaller files for large data sets, but comes at the cost of a fixed resolution. We will be using Python Matplotlib library to illustrate the concept of rasterization.","steps":[{"title":"Import libraries","body":["We need to import the required libraries before we start."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create data","body":["We will create some data which will be used to illustrate the rasterization concept."],"code":[{"lang":"python","text":"d = np.arange(100).reshape(10, 10)  # the values to be color-mapped\nx, y = np.meshgrid(np.arange(11), np.arange(11))\n\ntheta = 0.25*np.pi\nxx = x*np.cos(theta) - y*np.sin(theta)  # rotate x by -theta\nyy = x*np.sin(theta) + y*np.cos(theta)  # rotate y by -theta"}]},{"title":"Create a figure with four subplots","body":["Create a figure with four subplots","We will create a figure with four subplots to illustrate the different aspects of rasterization."],"code":[{"lang":"python","text":"fig, ((ax1, ax2), (ax3, ax4)) = plt.subplots(2, 2, layout=\"constrained\")"}]},{"title":"Create a pcolormesh plot without rasterization","body":["Create a pcolormesh plot without rasterization","We will create a pcolormesh plot without rasterization to illustrate the difference between rasterization and non-rasterization."],"code":[{"lang":"python","text":"ax1.set_aspect(1)\nax1.pcolormesh(xx, yy, d)\nax1.set_title(\"No Rasterization\")"}]},{"title":"Create a pcolormesh plot with rasterization","body":["Create a pcolormesh plot with rasterization","We will create a pcolormesh plot with rasterization to illustrate how rasterization can speed up rendering and produce smaller files."],"code":[{"lang":"python","text":"ax2.set_aspect(1)\nax2.set_title(\"Rasterization\")\nax2.pcolormesh(xx, yy, d, rasterized=True)"}]},{"title":"Create a pcolormesh plot with an overlaid text without rasterization","body":["Create a pcolormesh plot with an overlaid text without rasterization","We will create a pcolormesh plot with an overlaid text without rasterization to illustrate how vector graphics can maintain the advantages of vector graphics for some artists such as the axes and text."],"code":[{"lang":"python","text":"ax3.set_aspect(1)\nax3.pcolormesh(xx, yy, d)\nax3.text(0.5, 0.5, \"Text\", alpha=0.2,\n         va=\"center\", ha=\"center\", size=50, transform=ax3.transAxes)\nax3.set_title(\"No Rasterization\")"}]},{"title":"Create a pcolormesh plot with an overlaid text with rasterization","body":["Create a pcolormesh plot with an overlaid text with rasterization","We will create a pcolormesh plot with an overlaid text with rasterization to illustrate how rasterization can enable vector graphics to maintain the advantages of vector graphics for some artists such as the axes and text."],"code":[{"lang":"python","text":"ax4.set_aspect(1)\nm = ax4.pcolormesh(xx, yy, d, zorder=-10)\nax4.text(0.5, 0.5, \"Text\", alpha=0.2,\n         va=\"center\", ha=\"center\", size=50, transform=ax4.transAxes)\nax4.set_rasterization_zorder(0)\nax4.set_title(\"Rasterization z$<-10$\")"}]},{"title":"Save the figures","body":["We will save the figures in pdf and eps format."],"code":[{"lang":"python","text":"plt.savefig(\"test_rasterization.pdf\", dpi=150)\nplt.savefig(\"test_rasterization.eps\", dpi=150)\n\nif not plt.rcParams[\"text.usetex\"]:\n    plt.savefig(\"test_rasterization.svg\", dpi=150)\n    # svg backend currently ignores the dpi"}]}],"commands":[],"reference":[{"path":"reference.py","text":"plt.savefig(\"test_rasterization.pdf\", dpi=150)\nplt.savefig(\"test_rasterization.eps\", dpi=150)\n\nif not plt.rcParams[\"text.usetex\"]:\n    plt.savefig(\"test_rasterization.svg\", dpi=150)\n    # svg backend currently ignores the dpi"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-drawing-shapes-with-matplotlib-widgets":{"intro":"In this lab, we will learn how to use the RectangleSelector and EllipseSelector widgets in Matplotlib to draw a rectangle or ellipse from the initial click position to the current mouse position.","steps":[{"title":"Import necessary libraries","body":["We will start by importing the necessary libraries: Matplotlib, Numpy, and the RectangleSelector and EllipseSelector widgets."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom matplotlib.widgets import EllipseSelector, RectangleSelector"}]},{"title":"Define the select callback function","body":["Define the select callback function"],"code":[{"lang":"python","text":"def select_callback(eclick, erelease):\n    \"\"\"\n    Callback for line selection.\n\n    *eclick* and *erelease* are the press and release events.\n    \"\"\"\n    x1, y1 = eclick.xdata, eclick.ydata\n    x2, y2 = erelease.xdata, erelease.ydata\n    print(f\"({x1:3.2f}, {y1:3.2f}) --> ({x2:3.2f}, {y2:3.2f})\")\n    print(f\"The buttons you used were: {eclick.button} {erelease.button}\")"}]},{"title":"Define the toggle selector function","body":["Define the toggle selector function","The toggle selector function will be called every time the user presses the 't' key. This function will toggle the active status of the RectangleSelector and EllipseSelector widgets."],"code":[{"lang":"python","text":"def toggle_selector(event):\n    print('Key pressed.')\n    if event.key == 't':\n        for selector in selectors:\n            name = type(selector).__name__\n            if selector.active:\n                print(f'{name} deactivated.')\n                selector.set_active(False)\n            else:\n                print(f'{name} activated.')\n                selector.set_active(True)"}]},{"title":"Create the figure and subplots","body":["Create the figure and subplots","We will create a figure with two subplots, one for the RectangleSelector and one for the EllipseSelector."],"code":[{"lang":"python","text":"fig = plt.figure(layout='constrained')\naxs = fig.subplots(2)"}]},{"title":"Plot something on the subplots","body":["Plot something on the subplots","We will plot something on the subplots, so that the user can see the effect of the RectangleSelector and EllipseSelector."],"code":[{"lang":"python","text":"N = 100000  # If N is large one can see improvement by using blitting.\nx = np.linspace(0, 10, N)\n\nfor ax in axs:\n    ax.plot(x, np.sin(2*np.pi*x))  # plot something"}]},{"title":"Create the RectangleSelector and EllipseSelector widgets","body":["Create the RectangleSelector and EllipseSelector widgets","We will create the RectangleSelector and EllipseSelector widgets and add them to the subplots."],"code":[{"lang":"python","text":"selectors = []\nfor ax, selector_class in zip(axs, [RectangleSelector, EllipseSelector]):\n    ax.set_title(f\"Click and drag to draw a {selector_class.__name__}.\")\n    selectors.append(selector_class(\n        ax, select_callback,\n        useblit=True,\n        button=[1, 3],  # disable middle button\n        minspanx=5, minspany=5,\n        spancoords='pixels',\n        interactive=True))\n    fig.canvas.mpl_connect('key_press_event', toggle_selector)\naxs[0].set_title(\"Press 't' to toggle the selectors on and off.\\n\"\n                 + axs[0].get_title())"}]},{"title":"Show the plot","body":["Finally, we will show the plot to the user."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-resampling-data-using-matplotlib":{"intro":"In this lab, we will learn how to downsample data using Matplotlib in Python. Downsampling is the process of reducing the sample rate or sample size of a signal. We will use a class that will downsample the data and recompute when zoomed.","steps":[{"title":"Importing libraries","body":["We will start by importing the necessary libraries. We will be using Matplotlib and NumPy libraries for this task."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Defining the class","body":["We will define a class DataDisplayDownsampler that will downsample the data and recompute when zoomed. The constructor of the class will take the xdata and ydata as input parameters. We will set the maximum number of points to 50 and calculate the delta of xdata."],"code":[{"lang":"python","text":"class DataDisplayDownsampler:\n    def __init__(self, xdata, ydata):\n        self.origYData = ydata\n        self.origXData = xdata\n        self.max_points = 50\n        self.delta = xdata[-1] - xdata[0]"}]},{"title":"Downsampling data","body":["We will define a method downsample that will downsample the data. The method will take the xstart and xend as input parameters. We will get the points in the view range and dilate the mask by one to catch the points just outside of the view range to not truncate the line. We will sort out how many points to drop and mask the data. Finally, we will downsample the data and return the xdata and ydata."],"code":[{"lang":"python","text":"def downsample(self, xstart, xend):\n    # get the points in the view range\n    mask = (self.origXData > xstart) & (self.origXData < xend)\n    # dilate the mask by one to catch the points just outside\n    # of the view range to not truncate the line\n    mask = np.convolve([1, 1, 1], mask, mode='same').astype(bool)\n    # sort out how many points to drop\n    ratio = max(np.sum(mask) // self.max_points, 1)\n\n    # mask data\n    xdata = self.origXData[mask]\n    ydata = self.origYData[mask]\n\n    # downsample data\n    xdata = xdata[::ratio]\n    ydata = ydata[::ratio]\n\n    print(f\"using {len(ydata)} of {np.sum(mask)} visible points\")\n\n    return xdata, ydata"}]},{"title":"Updating the data","body":["We will define a method update that will update the data. The method will take the ax (axis) as an input parameter. We will update the line by getting the view limit and checking if the width of the view limit is different from delta. If the width of the view limit is different from delta, we will update the delta and get the xstart and xend. We will then set the data to the downsampled data and draw the idle."],"code":[{"lang":"python","text":"def update(self, ax):\n    # Update the line\n    lims = ax.viewLim\n    if abs(lims.width - self.delta) > 1e-8:\n        self.delta = lims.width\n        xstart, xend = lims.intervalx\n        self.line.set_data(*self.downsample(xstart, xend))\n        ax.figure.canvas.draw_idle()"}]},{"title":"Creating the signal","body":["We will create a signal using NumPy. We will create an array xdata using linspace function with start=16, stop=365 and num= (365-16)\\*4. We will create an array ydata using sin and cos functions."],"code":[{"lang":"python","text":"xdata = np.linspace(16, 365, (365-16)*4)\nydata = np.sin(2*np.pi*xdata/153) + np.cos(2*np.pi*xdata/127)"}]},{"title":"Creating the plot","body":["We will create a plot using Matplotlib. We will create an instance d of the DataDisplayDownsampler class using xdata and ydata. We will create a figure and an axis using subplots function. We will hook up the line and set the autoscale on False. We will connect for changing the view limits, set the x limit and show the plot."],"code":[{"lang":"python","text":"d = DataDisplayDownsampler(xdata, ydata)\nfig, ax = plt.subplots()\nd.line, = ax.plot(xdata, ydata, 'o-')\nax.set_autoscale_on(False)\nax.callbacks.connect('xlim_changed', d.update)\nax.set_xlim(16, 365)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"d = DataDisplayDownsampler(xdata, ydata)\nfig, ax = plt.subplots()\nd.line, = ax.plot(xdata, ydata, 'o-')\nax.set_autoscale_on(False)\nax.callbacks.connect('xlim_changed', d.update)\nax.set_xlim(16, 365)\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-3d-plot-animation":{"intro":"This lab will guide you on how to create a simple animation of a rotating 3D plot about all three axes using Matplotlib. We will use a sample dataset to create a basic wireframe, set axis labels, and rotate the axes.","steps":[{"title":"Import Libraries and Dataset","body":["First, we need to import the necessary libraries and dataset. In this example, we will use the matplotlib and mpl_toolkits.mplot3d libraries to create the 3D plot, and the axes3d.get_test_data() function to generate a sample dataset."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom mpl_toolkits.mplot3d import axes3d\n\n# Generate sample dataset\nX, Y, Z = axes3d.get_test_data(0.05)"}]},{"title":"Create a 3D Plot","body":["Next, we will create a 3D plot using the plt.figure() and fig.add_subplot() functions. We will also use the ax.plot_wireframe() function to plot the dataset as a wireframe."],"code":[{"lang":"python","text":"# Create 3D plot\nfig = plt.figure()\nax = fig.add_subplot(projection='3d')\n\n# Plot wireframe\nax.plot_wireframe(X, Y, Z, rstride=10, cstride=10)"}]},{"title":"Set Axis Labels","body":["We will now set the axis labels for the 3D plot using the ax.set_xlabel(), ax.set_ylabel(), and ax.set_zlabel() functions."],"code":[{"lang":"python","text":"# Set axis labels\nax.set_xlabel('x')\nax.set_ylabel('y')\nax.set_zlabel('z')"}]},{"title":"Rotate the Axes and Update the Plot","body":["Rotate the Axes and Update the Plot","Finally, we will rotate the axes and update the plot using a for loop that cycles through a full rotation of elevation, then azimuth, roll, and all. We will use the ax.view_init() function to update the axis view and title, and the plt.title(), plt.draw(), and plt.pause() functions to display the animation."],"code":[{"lang":"python","text":"# Rotate the axes and update the plot\nfor angle in range(0, 360*4 + 1):\n    # Normalize the angle to the range [-180, 180] for display\n    angle_norm = (angle + 180) % 360 - 180\n\n    # Cycle through a full rotation of elevation, then azimuth, roll, and all\n    elev = azim = roll = 0\n    if angle <= 360:\n        elev = angle_norm\n    elif angle <= 360*2:\n        azim = angle_norm\n    elif angle <= 360*3:\n        roll = angle_norm\n    else:\n        elev = azim = roll = angle_norm\n\n    # Update the axis view and title\n    ax.view_init(elev, azim, roll)\n    plt.title('Elevation: %d°, Azimuth: %d°, Roll: %d°' % (elev, azim, roll))\n\n    # Display animation\n    plt.draw()\n    plt.pause(.001)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Rotate the axes and update the plot\nfor angle in range(0, 360*4 + 1):\n    # Normalize the angle to the range [-180, 180] for display\n    angle_norm = (angle + 180) % 360 - 180\n\n    # Cycle through a full rotation of elevation, then azimuth, roll, and all\n    elev = azim = roll = 0\n    if angle <= 360:\n        elev = angle_norm\n    elif angle <= 360*2:\n        azim = angle_norm\n    elif angle <= 360*3:\n        roll = angle_norm\n    else:\n        elev = azim = roll = angle_norm\n\n    # Update the axis view and title\n    ax.view_init(elev, azim, roll)\n    plt.title('Elevation: %d°, Azimuth: %d°, Roll: %d°' % (elev, azim, roll))\n\n    # Display animation\n    plt.draw()\n    plt.pause(.001)"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-creating-sankey-diagrams":{"intro":"Sankey diagrams are flow diagrams that show the movement of resources or energy between different stages or systems. In this tutorial, we will use the Matplotlib library in Python to create Sankey diagrams.","steps":[{"title":"Import necessary libraries","body":["Before we start creating Sankey diagrams, we need to import the necessary libraries. In this tutorial, we will be using the Matplotlib library."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom matplotlib.sankey import Sankey"}]},{"title":"Create a simple Sankey diagram","body":["Create a simple Sankey diagram","We will start by creating a simple Sankey diagram that demonstrates how to use the Sankey class.","This code will produce a Sankey diagram with default settings, which includes the labels and orientations of the flows. The resulting diagram will be displayed with the title \"The default settings produce a diagram like this.\""],"code":[{"lang":"python","text":"Sankey(flows=[0.25, 0.15, 0.60, -0.20, -0.15, -0.05, -0.50, -0.10],\n       labels=['', '', '', 'First', 'Second', 'Third', 'Fourth', 'Fifth'],\n       orientations=[-1, 1, 0, 1, 1, 1, 0, -1]).finish()\nplt.title(\"The default settings produce a diagram like this.\")"}]},{"title":"Customize the Sankey diagram","body":["We can customize the Sankey diagram by changing the flows, labels, orientations, and other parameters. In this example, we will create a diagram with longer paths and a label in the middle.","This code will create a Sankey diagram with longer paths, a label in the middle, and other customized parameters. The resulting diagram will be displayed with the title \"Flow Diagram of a Widget.\""],"code":[{"lang":"python","text":"fig = plt.figure()\nax = fig.add_subplot(1, 1, 1, xticks=[], yticks=[],\n                     title=\"Flow Diagram of a Widget\")\nsankey = Sankey(ax=ax, scale=0.01, offset=0.2, head_angle=180,\n                format='%.0f', unit='%')\nsankey.add(flows=[25, 0, 60, -10, -20, -5, -15, -10, -40],\n           labels=['', '', '', 'First', 'Second', 'Third', 'Fourth',\n                   'Fifth', 'Hurray!'],\n           orientations=[-1, 1, 0, 1, 1, 1, -1, -1, 0],\n           pathlengths=[0.25, 0.25, 0.25, 0.25, 0.25, 0.6, 0.25, 0.25,\n                        0.25],\n           patchlabel=\"Widget\\nA\")  # Arguments to matplotlib.patches.PathPatch\ndiagrams = sankey.finish()\ndiagrams[0].texts[-1].set_color('r')\ndiagrams[0].text.set_fontweight('bold')"}]},{"title":"Connect two systems in a Sankey diagram","body":["Connect two systems in a Sankey diagram","We can also connect two systems in a Sankey diagram. In this example, we will create a diagram with two systems that are connected.","This code will create a Sankey diagram with two systems that are connected. The resulting diagram will be displayed with the title \"Two Systems.\""],"code":[{"lang":"python","text":"fig = plt.figure()\nax = fig.add_subplot(1, 1, 1, xticks=[], yticks=[], title=\"Two Systems\")\nflows = [0.25, 0.15, 0.60, -0.10, -0.05, -0.25, -0.15, -0.10, -0.35]\nsankey = Sankey(ax=ax, unit=None)\nsankey.add(flows=flows, label='one',\n           orientations=[-1, 1, 0, 1, 1, 1, -1, -1, 0])\nsankey.add(flows=[-0.25, 0.15, 0.1], label='two',\n           orientations=[-1, -1, -1], prior=0, connect=(0, 0))\ndiagrams = sankey.finish()\ndiagrams[-1].patch.set_hatch('/')\nplt.legend()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig = plt.figure()\nax = fig.add_subplot(1, 1, 1, xticks=[], yticks=[], title=\"Two Systems\")\nflows = [0.25, 0.15, 0.60, -0.10, -0.05, -0.25, -0.15, -0.10, -0.35]\nsankey = Sankey(ax=ax, unit=None)\nsankey.add(flows=flows, label='one',\n           orientations=[-1, 1, 0, 1, 1, 1, -1, -1, 0])\nsankey.add(flows=[-0.25, 0.15, 0.1], label='two',\n           orientations=[-1, -1, -1], prior=0, connect=(0, 0))\ndiagrams = sankey.finish()\ndiagrams[-1].patch.set_hatch('/')\nplt.legend()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"}};
